INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 1, 'Quel peuple ancien a construit les aqueducs en Europe ?', 'Les Romains', ARRAY['Les Grecs', 'Les Celtes', 'Les Phéniciens'], 'fr', true, 'Les Romains étaient des maîtres ingénieurs et ont construit des aqueducs à travers tout leur empire.'),
('history', 1, 'Quel pays a offert la Statue de la Liberté aux États-Unis ?', 'La France', ARRAY['L''Angleterre', 'L''Espagne', 'L''Italie'], 'fr', true, 'La Statue de la Liberté a été offerte par la France en 1886 en signe d''amitié.'),
('history', 1, 'Comment s''appelle l''écriture des anciens Égyptiens ?', 'Les hiéroglyphes', ARRAY['Le cunéiforme', 'L''alphabet grec', 'Les runes'], 'fr', true, 'Les hiéroglyphes étaient un système d''écriture composé de symboles et dessins sacrés.'),
('history', 1, 'Quelle reine de France a été surnommée l''Autrichienne ?', 'Marie-Antoinette', ARRAY['Catherine de Médicis', 'Anne d''Autriche', 'Marie de Médicis'], 'fr', true, 'Marie-Antoinette, originaire d''Autriche, épousa Louis XVI en 1770.'),
('history', 1, 'Quel était le moyen de transport principal au Moyen Âge ?', 'Le cheval', ARRAY['La voiture', 'Le train', 'Le chameau'], 'fr', true, 'Le cheval était le principal moyen de transport et de guerre au Moyen Âge en Europe.'),
('history', 1, 'Quel célèbre général a traversé les Alpes avec des éléphants ?', 'Hannibal', ARRAY['Jules César', 'Alexandre le Grand', 'Napoléon'], 'fr', true, 'Hannibal Barca, général carthaginois, a traversé les Alpes en 218 av. J.-C. pour attaquer Rome.'),
('history', 1, 'Quel instrument de musique est associé aux pharaons d''Égypte ?', 'La harpe', ARRAY['Le piano', 'La guitare', 'Le violon'], 'fr', true, 'La harpe était un instrument joué dans l''Égypte ancienne lors des cérémonies royales.'),
('history', 1, 'Quelle ville italienne est célèbre pour ses gondoles ?', 'Venise', ARRAY['Rome', 'Florence', 'Naples'], 'fr', true, 'Venise, construite sur l''eau, utilise les gondoles comme moyen de transport depuis des siècles.'),
('history', 1, 'Quel animal les Égyptiens considéraient-ils comme sacré ?', 'Le chat', ARRAY['Le chien', 'Le serpent', 'L''aigle'], 'fr', true, 'Les chats étaient vénérés en Égypte ancienne et associés à la déesse Bastet.'),
('history', 1, 'Quel peuple a inventé les Jeux Olympiques antiques ?', 'Les Grecs', ARRAY['Les Romains', 'Les Perses', 'Les Égyptiens'], 'fr', true, 'Les premiers Jeux Olympiques ont eu lieu à Olympie, en Grèce, en 776 av. J.-C.'),
('history', 1, 'Comment s''appelle le grand navire qui a coulé en 1912 ?', 'Le Titanic', ARRAY['Le Lusitania', 'Le Bismarck', 'Le Britannic'], 'fr', true, 'Le Titanic a heurté un iceberg lors de son voyage inaugural et a sombré dans l''Atlantique Nord.'),
('history', 1, 'Quel roi de France a été guillotiné pendant la Révolution ?', 'Louis XVI', ARRAY['Louis XIV', 'Louis XV', 'Charles X'], 'fr', true, 'Louis XVI a été exécuté par guillotine le 21 janvier 1793 place de la Révolution à Paris.'),
('history', 1, 'Quel peuple construisait des pyramides en Amérique centrale ?', 'Les Mayas', ARRAY['Les Vikings', 'Les Celtes', 'Les Perses'], 'fr', true, 'Les Mayas ont bâti d''impressionnantes pyramides-temples dans la péninsule du Yucatan.'),
('history', 1, 'Qui a écrit les pièces Roméo et Juliette et Hamlet ?', 'William Shakespeare', ARRAY['Charles Dickens', 'Victor Hugo', 'Molière'], 'fr', true, 'Shakespeare est le plus célèbre dramaturge anglais, actif à la fin du XVIe siècle.'),
('history', 1, 'Quelle grande muraille a été construite pour protéger la Chine ?', 'La Grande Muraille de Chine', ARRAY['Le mur d''Hadrien', 'Le mur de Berlin', 'Les remparts de Carcassonne'], 'fr', true, 'La Grande Muraille de Chine mesure plus de 20 000 km et fut construite sur plusieurs siècles.'),
('history', 1, 'De quel pays Cléopâtre était-elle la reine ?', 'L''Égypte', ARRAY['La Grèce', 'Rome', 'La Perse'], 'fr', true, 'Cléopâtre VII fut la dernière reine d''Égypte de la dynastie ptolémaïque.'),
('history', 1, 'Quel matériau les chevaliers portaient-ils pour se protéger ?', 'Une armure', ARRAY['Un costume', 'Une toge', 'Un kimono'], 'fr', true, 'Les chevaliers du Moyen Âge portaient des armures en métal pour se protéger au combat.'),
('history', 1, 'Quel peuple naviguait sur des drakkars ?', 'Les Vikings', ARRAY['Les Romains', 'Les Grecs', 'Les Phéniciens'], 'fr', true, 'Les Vikings, originaires de Scandinavie, naviguaient sur des drakkars entre le VIIIe et le XIe siècle.'),
('history', 1, 'Quel est le nom du premier avion des frères Wright ?', 'Le Flyer', ARRAY['Le Spirit', 'L''Albatros', 'Le Concorde'], 'fr', true, 'Le Wright Flyer a effectué le premier vol motorisé contrôlé le 17 décembre 1903.'),
('history', 1, 'Quel philosophe grec est connu pour avoir bu la ciguë ?', 'Socrate', ARRAY['Platon', 'Aristote', 'Épicure'], 'fr', true, 'Socrate fut condamné à mort en 399 av. J.-C. et but la ciguë à Athènes.'),
('history', 1, 'Quel empire était gouverné depuis Constantinople ?', 'L''Empire byzantin', ARRAY['L''Empire romain', 'L''Empire perse', 'L''Empire mongol'], 'fr', true, 'L''Empire byzantin, aussi appelé Empire romain d''Orient, avait sa capitale à Constantinople.'),
('history', 1, 'Quel roi de France était surnommé Saint Louis ?', 'Louis IX', ARRAY['Louis XIV', 'Louis XII', 'Louis VII'], 'fr', true, 'Louis IX, roi de France de 1226 à 1270, fut canonisé en 1297 pour sa piété.'),
('history', 1, 'Quelle invention a révolutionné l''agriculture au XIXe siècle ?', 'La machine à vapeur', ARRAY['L''ordinateur', 'L''électricité', 'Le téléphone'], 'fr', true, 'La machine à vapeur a permis de mécaniser l''agriculture et de transformer l''industrie.'),
('history', 1, 'Quel explorateur portugais a atteint l''Inde par la mer ?', 'Vasco de Gama', ARRAY['Christophe Colomb', 'Magellan', 'Marco Polo'], 'fr', true, 'Vasco de Gama a atteint Calicut, en Inde, en 1498 en contournant l''Afrique.'),
('history', 1, 'Quel monument de Paris abrite le tombeau de Napoléon ?', 'Les Invalides', ARRAY['Le Panthéon', 'Notre-Dame', 'L''Arc de Triomphe'], 'fr', true, 'Le tombeau de Napoléon Ier se trouve sous le dôme des Invalides à Paris depuis 1840.'),
('history', 1, 'Quel peuple antique vivait dans la ville de Sparte ?', 'Les Spartiates', ARRAY['Les Athéniens', 'Les Perses', 'Les Romains'], 'fr', true, 'Sparte était une cité-État grecque connue pour ses redoutables guerriers.'),
('history', 1, 'Quelle catastrophe naturelle a détruit Pompéi ?', 'Une éruption volcanique', ARRAY['Un tremblement de terre', 'Un tsunami', 'Une inondation'], 'fr', true, 'L''éruption du Vésuve en 79 apr. J.-C. a enseveli Pompéi sous les cendres.'),
('history', 1, 'Qui a découvert la pénicilline ?', 'Alexander Fleming', ARRAY['Louis Pasteur', 'Marie Curie', 'Robert Koch'], 'fr', true, 'Alexander Fleming a découvert la pénicilline par accident en 1928.'),
('history', 1, 'Quel pays a été le premier à envoyer un satellite dans l''espace ?', 'L''URSS', ARRAY['Les États-Unis', 'La France', 'La Chine'], 'fr', true, 'L''URSS a lancé Spoutnik, le premier satellite artificiel, le 4 octobre 1957.'),
('history', 1, 'Comment s''appelait le palais des rois de France à Paris ?', 'Le Louvre', ARRAY['Versailles', 'Fontainebleau', 'Les Tuileries'], 'fr', true, 'Le Louvre fut la résidence royale à Paris avant que Louis XIV ne s''installe à Versailles.'),
('history', 1, 'Quel continent les Européens ont-ils colonisé massivement au XIXe siècle ?', 'L''Afrique', ARRAY['L''Asie', 'L''Amérique du Sud', 'L''Océanie'], 'fr', true, 'La conférence de Berlin de 1884-1885 a organisé le partage colonial de l''Afrique.'),
('history', 1, 'Quelle guerre oppose les Bleus et les Gris aux États-Unis ?', 'La Guerre de Sécession', ARRAY['La Guerre d''Indépendance', 'La Guerre de Sept Ans', 'La Guerre du Mexique'], 'fr', true, 'La Guerre de Sécession (1861-1865) opposa le Nord et le Sud des États-Unis.'),
('history', 1, 'Quel savant italien a affirmé que la Terre tournait autour du Soleil ?', 'Galilée', ARRAY['Copernic', 'Newton', 'Kepler'], 'fr', true, 'Galilée a défendu l''héliocentrisme et fut condamné par l''Inquisition en 1633.'),
('history', 1, 'Quel événement marque le début du Moyen Âge ?', 'La chute de Rome', ARRAY['Les croisades', 'La peste noire', 'La découverte de l''Amérique'], 'fr', true, 'La chute de l''Empire romain d''Occident en 476 marque traditionnellement le début du Moyen Âge.'),
('history', 1, 'Quel célèbre pirate portait un drapeau noir avec une tête de mort ?', 'Barbe Noire', ARRAY['Jack Sparrow', 'Francis Drake', 'Henry Morgan'], 'fr', true, 'Edward Teach, dit Barbe Noire, terrorisait les Caraïbes au début du XVIIIe siècle.'),
('history', 1, 'Quel pays européen a colonisé le Brésil ?', 'Le Portugal', ARRAY['L''Espagne', 'La France', 'L''Angleterre'], 'fr', true, 'Le Brésil fut colonisé par le Portugal à partir de 1500 et devint indépendant en 1822.'),
('history', 1, 'Comment s''appelait le dieu du soleil chez les Égyptiens ?', 'Rê', ARRAY['Osiris', 'Anubis', 'Horus'], 'fr', true, 'Rê (ou Rê-Atoum) était le dieu du soleil et l''une des divinités les plus importantes d''Égypte.'),
('history', 1, 'Quel monument romain accueillait des combats de gladiateurs ?', 'Le Colisée', ARRAY['Le Panthéon', 'Le Forum', 'Les Thermes'], 'fr', true, 'Le Colisée de Rome pouvait accueillir entre 50 000 et 80 000 spectateurs.'),
('history', 1, 'En quelle année l''homme a-t-il inventé la roue ?', 'Vers 3500 av. J.-C.', ARRAY['Vers 1000 av. J.-C.', 'Vers 5000 av. J.-C.', 'Vers 500 av. J.-C.'], 'fr', true, 'La roue a été inventée en Mésopotamie vers 3500 av. J.-C. pour le transport et la poterie.'),
('history', 1, 'Quel événement a mis fin à la Seconde Guerre mondiale en Europe ?', 'La capitulation de l''Allemagne', ARRAY['Le débarquement en Normandie', 'La bombe atomique', 'La libération de Paris'], 'fr', true, 'L''Allemagne a capitulé le 8 mai 1945, marquant la fin de la guerre en Europe.'),
('history', 1, 'Qui était Jeanne d''Arc ?', 'Une héroïne française de la Guerre de Cent Ans', ARRAY['Une reine de France', 'Une impératrice romaine', 'Une exploratrice'], 'fr', true, 'Jeanne d''Arc a mené les troupes françaises contre les Anglais et fut brûlée en 1431.'),
('history', 1, 'Quel métier faisaient les samouraïs au Japon ?', 'Guerrier', ARRAY['Moine', 'Marchand', 'Artisan'], 'fr', true, 'Les samouraïs étaient des guerriers de l''élite militaire japonaise du XIIe au XIXe siècle.'),
('history', 1, 'Quelle civilisation ancienne a inventé la démocratie ?', 'Les Grecs', ARRAY['Les Romains', 'Les Égyptiens', 'Les Perses'], 'fr', true, 'La démocratie est née à Athènes au Ve siècle av. J.-C. sous Périclès.'),
('history', 1, 'Quel objet les archéologues ont-ils utilisé pour déchiffrer les hiéroglyphes ?', 'La pierre de Rosette', ARRAY['Le papyrus d''Ani', 'La tablette de Gilgamesh', 'Le code d''Hammurabi'], 'fr', true, 'La pierre de Rosette, trouvée en 1799, a permis à Champollion de déchiffrer les hiéroglyphes.'),
('history', 1, 'Quel peuple a fondé la ville de Carthage ?', 'Les Phéniciens', ARRAY['Les Grecs', 'Les Romains', 'Les Berbères'], 'fr', true, 'Carthage, dans l''actuelle Tunisie, fut fondée par les Phéniciens vers 814 av. J.-C.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 2, 'Quel traité a mis fin à la Première Guerre mondiale ?', 'Le traité de Versailles', ARRAY['Le traité de Paris', 'Le traité de Westphalie', 'Le traité de Vienne'], 'fr', true, 'Le traité de Versailles a été signé le 28 juin 1919, mettant fin officiellement à la Grande Guerre.'),
('history', 2, 'En quelle année Napoléon a-t-il été couronné empereur ?', '1804', ARRAY['1799', '1806', '1812'], 'fr', true, 'Napoléon Bonaparte s''est couronné empereur des Français le 2 décembre 1804 à Notre-Dame de Paris.'),
('history', 2, 'Quel pharaon a fait construire le temple d''Abou Simbel ?', 'Ramsès II', ARRAY['Khéops', 'Toutânkhamon', 'Akhenaton'], 'fr', true, 'Ramsès II a fait ériger les temples d''Abou Simbel en Nubie au XIIIe siècle av. J.-C.'),
('history', 2, 'Quelle bataille a mis fin au règne de Napoléon en 1815 ?', 'Waterloo', ARRAY['Austerlitz', 'Trafalgar', 'Iéna'], 'fr', true, 'La bataille de Waterloo, le 18 juin 1815, a scellé la défaite définitive de Napoléon.'),
('history', 2, 'Quel roi de France a signé l''édit de Nantes ?', 'Henri IV', ARRAY['Louis XIII', 'François Ier', 'Louis XIV'], 'fr', true, 'Henri IV a signé l''édit de Nantes en 1598, accordant la liberté de culte aux protestants.'),
('history', 2, 'Quel empire a conquis Constantinople en 1453 ?', 'L''Empire ottoman', ARRAY['L''Empire mongol', 'L''Empire perse', 'L''Empire arabe'], 'fr', true, 'Le sultan Mehmet II a pris Constantinople le 29 mai 1453, mettant fin à l''Empire byzantin.'),
('history', 2, 'Qui a mené la Longue Marche en Chine ?', 'Mao Zedong', ARRAY['Sun Yat-sen', 'Tchang Kaï-chek', 'Deng Xiaoping'], 'fr', true, 'Mao Zedong a dirigé la Longue Marche de 1934 à 1935 pour sauver l''Armée rouge chinoise.'),
('history', 2, 'En quelle année la Bastille a-t-elle été prise ?', '1789', ARRAY['1791', '1793', '1799'], 'fr', true, 'La prise de la Bastille le 14 juillet 1789 est le symbole du début de la Révolution française.'),
('history', 2, 'Quel scientifique a formulé les lois de la gravitation universelle ?', 'Isaac Newton', ARRAY['Albert Einstein', 'Galilée', 'Johannes Kepler'], 'fr', true, 'Isaac Newton a publié ses lois de la gravitation dans les Principia Mathematica en 1687.'),
('history', 2, 'Quelle dynastie a régné sur la France de 987 à 1328 ?', 'Les Capétiens', ARRAY['Les Mérovingiens', 'Les Carolingiens', 'Les Valois'], 'fr', true, 'La dynastie capétienne a commencé avec Hugues Capet en 987 et a duré plus de trois siècles.'),
('history', 2, 'Quel pays a été divisé en deux après la Seconde Guerre mondiale ?', 'L''Allemagne', ARRAY['La France', 'L''Italie', 'Le Japon'], 'fr', true, 'L''Allemagne fut divisée en RFA et RDA en 1949, jusqu''à la réunification de 1990.'),
('history', 2, 'Qui a fondé l''Empire mongol au XIIIe siècle ?', 'Gengis Khan', ARRAY['Kubilai Khan', 'Tamerlan', 'Attila'], 'fr', true, 'Gengis Khan a unifié les tribus mongoles et fondé le plus grand empire continental de l''histoire.'),
('history', 2, 'Quelle guerre a duré de 1337 à 1453 ?', 'La Guerre de Cent Ans', ARRAY['La Guerre de Sept Ans', 'Les Croisades', 'La Guerre de Trente Ans'], 'fr', true, 'La Guerre de Cent Ans opposa la France et l''Angleterre pendant 116 ans.'),
('history', 2, 'Quel navigateur anglais a exploré l''Australie et la Nouvelle-Zélande ?', 'James Cook', ARRAY['Francis Drake', 'Walter Raleigh', 'Henry Hudson'], 'fr', true, 'Le capitaine James Cook a cartographié les côtes de l''Australie et de la Nouvelle-Zélande en 1770.'),
('history', 2, 'En quelle année l''esclavage a-t-il été aboli en France ?', '1848', ARRAY['1789', '1830', '1870'], 'fr', true, 'L''abolition définitive de l''esclavage en France fut décrétée le 27 avril 1848 par Victor Schoelcher.'),
('history', 2, 'Quel empereur romain a fait du christianisme la religion officielle ?', 'Théodose Ier', ARRAY['Constantin', 'Néron', 'Auguste'], 'fr', true, 'Théodose Ier a fait du christianisme la religion d''État de l''Empire romain en 380.'),
('history', 2, 'Quelle révolution industrielle a commencé en Angleterre au XVIIIe siècle ?', 'La première révolution industrielle', ARRAY['La deuxième révolution industrielle', 'La révolution numérique', 'La révolution verte'], 'fr', true, 'La première révolution industrielle a débuté vers 1760 en Angleterre avec la machine à vapeur.'),
('history', 2, 'Quel roi de France a fait construire le château de Chambord ?', 'François Ier', ARRAY['Louis XIV', 'Henri IV', 'Louis XIII'], 'fr', true, 'François Ier a ordonné la construction du château de Chambord en 1519 dans la vallée de la Loire.'),
('history', 2, 'Quelle bataille navale a opposé la France et l''Angleterre en 1805 ?', 'La bataille de Trafalgar', ARRAY['La bataille de Lépante', 'La bataille de Salamine', 'La bataille d''Aboukir'], 'fr', true, 'La bataille de Trafalgar, remportée par l''amiral Nelson, mit fin aux ambitions navales de Napoléon.'),
('history', 2, 'Quel est le nom du code de lois créé par Napoléon ?', 'Le Code civil', ARRAY['Le Code pénal', 'Le Code noir', 'Le Code de Justinien'], 'fr', true, 'Le Code civil, ou Code Napoléon, promulgué en 1804, est la base du droit français actuel.'),
('history', 2, 'Quelle civilisation a construit la cité de Tenochtitlan ?', 'Les Aztèques', ARRAY['Les Mayas', 'Les Incas', 'Les Olmèques'], 'fr', true, 'Tenochtitlan, fondée en 1325, était la capitale de l''Empire aztèque sur l''actuel site de Mexico.'),
('history', 2, 'En quelle année le mur de Berlin est-il tombé ?', '1989', ARRAY['1991', '1987', '1985'], 'fr', true, 'Le mur de Berlin est tombé le 9 novembre 1989, symbole de la fin de la Guerre froide.'),
('history', 2, 'Qui a dirigé l''Inde vers l''indépendance par la non-violence ?', 'Gandhi', ARRAY['Nehru', 'Tagore', 'Ambedkar'], 'fr', true, 'Le Mahatma Gandhi a mené un mouvement de désobéissance civile non-violente contre le colonialisme britannique.'),
('history', 2, 'Quelle invention de Gutenberg a transformé la diffusion du savoir ?', 'L''imprimerie à caractères mobiles', ARRAY['Le papier', 'L''encre', 'La plume d''oie'], 'fr', true, 'Gutenberg a inventé l''imprimerie à caractères mobiles vers 1440 à Mayence, en Allemagne.'),
('history', 2, 'Quel siècle est surnommé le Siècle des Lumières ?', 'Le XVIIIe siècle', ARRAY['Le XVIIe siècle', 'Le XIXe siècle', 'Le XVIe siècle'], 'fr', true, 'Le XVIIIe siècle est le Siècle des Lumières, marqué par Voltaire, Rousseau et Diderot.'),
('history', 2, 'Quel événement a déclenché la Première Guerre mondiale ?', 'L''assassinat de l''archiduc François-Ferdinand', ARRAY['L''invasion de la Pologne', 'La bataille de la Marne', 'Le traité de Versailles'], 'fr', true, 'L''assassinat de l''archiduc François-Ferdinand à Sarajevo le 28 juin 1914 a déclenché la Grande Guerre.'),
('history', 2, 'Qui a peint le plafond de la chapelle Sixtine ?', 'Michel-Ange', ARRAY['Léonard de Vinci', 'Raphaël', 'Botticelli'], 'fr', true, 'Michel-Ange a peint le plafond de la chapelle Sixtine entre 1508 et 1512 au Vatican.'),
('history', 2, 'Quel pays a lancé l''attaque de Pearl Harbor en 1941 ?', 'Le Japon', ARRAY['L''Allemagne', 'L''Italie', 'La Russie'], 'fr', true, 'Le Japon a attaqué la base navale américaine de Pearl Harbor le 7 décembre 1941.'),
('history', 2, 'Quelle civilisation a inventé le zéro ?', 'Les Indiens', ARRAY['Les Arabes', 'Les Grecs', 'Les Chinois'], 'fr', true, 'Le concept du zéro comme nombre a été développé en Inde vers le Ve siècle.'),
('history', 2, 'Quel document a été signé en Angleterre en 1215 par le roi Jean ?', 'La Magna Carta', ARRAY['La Déclaration des droits', 'L''Habeas Corpus', 'La Pétition des droits'], 'fr', true, 'La Magna Carta, signée en 1215, limitait le pouvoir royal et posait les bases des libertés anglaises.'),
('history', 2, 'Quelle île Napoléon a-t-il été exilé pour la dernière fois ?', 'Sainte-Hélène', ARRAY['L''île d''Elbe', 'La Corse', 'La Sardaigne'], 'fr', true, 'Napoléon a été exilé à Sainte-Hélène en 1815, où il est mort en 1821.'),
('history', 2, 'Quel pays a été le berceau de la Renaissance ?', 'L''Italie', ARRAY['La France', 'L''Allemagne', 'L''Angleterre'], 'fr', true, 'La Renaissance est née en Italie au XIVe siècle, notamment à Florence sous les Médicis.'),
('history', 2, 'Qui a prononcé le discours « I have a dream » ?', 'Martin Luther King', ARRAY['Malcolm X', 'Rosa Parks', 'Barack Obama'], 'fr', true, 'Martin Luther King a prononcé ce célèbre discours le 28 août 1963 à Washington.'),
('history', 2, 'Quelle guerre a opposé les États-Unis au Vietnam ?', 'La guerre du Vietnam', ARRAY['La guerre de Corée', 'La guerre du Golfe', 'La guerre froide'], 'fr', true, 'La guerre du Vietnam a duré de 1955 à 1975 et s''est soldée par la victoire du Nord-Vietnam.'),
('history', 2, 'En quelle année la Déclaration des droits de l''homme a-t-elle été adoptée ?', '1789', ARRAY['1791', '1793', '1776'], 'fr', true, 'La Déclaration des droits de l''homme et du citoyen a été adoptée le 26 août 1789.'),
('history', 2, 'Quel empire s''étendait de l''Espagne à l''Inde au VIIIe siècle ?', 'L''Empire arabe (Omeyyade)', ARRAY['L''Empire romain', 'L''Empire mongol', 'L''Empire ottoman'], 'fr', true, 'L''Empire omeyyade au VIIIe siècle s''étendait de la péninsule ibérique jusqu''aux confins de l''Inde.'),
('history', 2, 'Quel événement a marqué le début de la conquête spatiale ?', 'Le lancement de Spoutnik', ARRAY['Le premier pas sur la Lune', 'Le vol de Gagarine', 'Le programme Apollo'], 'fr', true, 'Le lancement de Spoutnik par l''URSS en 1957 a inauguré l''ère spatiale.'),
('history', 2, 'Quelle bataille est considérée comme la plus grande victoire de Napoléon ?', 'Austerlitz', ARRAY['Waterloo', 'Iéna', 'Marengo'], 'fr', true, 'La bataille d''Austerlitz, le 2 décembre 1805, est surnommée la bataille des Trois Empereurs.'),
('history', 2, 'Quel peuple a construit Angkor Vat au Cambodge ?', 'Les Khmers', ARRAY['Les Thaïs', 'Les Birmans', 'Les Vietnamiens'], 'fr', true, 'Angkor Vat a été construit par l''Empire khmer au XIIe siècle, sous le roi Suryavarman II.'),
('history', 2, 'En quelle année Christophe Colomb a-t-il atteint les Bahamas ?', '1492', ARRAY['1498', '1504', '1488'], 'fr', true, 'Christophe Colomb a accosté aux Bahamas le 12 octobre 1492 lors de son premier voyage.'),
('history', 2, 'Quel mouvement artistique est né à Florence au XIVe siècle ?', 'La Renaissance', ARRAY['Le Baroque', 'Le Romantisme', 'Le Classicisme'], 'fr', true, 'La Renaissance est née à Florence, portée par des artistes comme Giotto et des mécènes comme les Médicis.'),
('history', 2, 'Qui a été le premier président de la Ve République française ?', 'Charles de Gaulle', ARRAY['René Coty', 'Georges Pompidou', 'François Mitterrand'], 'fr', true, 'Charles de Gaulle a fondé la Ve République en 1958 et en fut le premier président.'),
('history', 2, 'Quelle invention a permis de naviguer en haute mer au XVe siècle ?', 'La caravelle', ARRAY['Le galion', 'La frégate', 'Le cuirassé'], 'fr', true, 'La caravelle, navire léger et maniable, a permis les grandes explorations maritimes du XVe siècle.'),
('history', 2, 'Quel pays a subi les bombardements atomiques de 1945 ?', 'Le Japon', ARRAY['L''Allemagne', 'L''Italie', 'La Chine'], 'fr', true, 'Les bombes atomiques ont été larguées sur Hiroshima et Nagasaki en août 1945.'),
('history', 2, 'Quel grand conquérant a fondé la ville d''Alexandrie en Égypte ?', 'Alexandre le Grand', ARRAY['Jules César', 'Ramsès II', 'Ptolémée'], 'fr', true, 'Alexandre le Grand a fondé Alexandrie en 331 av. J.-C. lors de sa conquête de l''Égypte.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 3, 'Quel traité de 1648 a mis fin à la Guerre de Trente Ans ?', 'Le traité de Westphalie', ARRAY['Le traité de Versailles', 'Le traité d''Utrecht', 'Le traité de Tordesillas'], 'fr', true, 'Les traités de Westphalie en 1648 ont redessiné la carte politique de l''Europe.'),
('history', 3, 'Qui était le sultan ottoman lors de la prise de Constantinople ?', 'Mehmet II', ARRAY['Soliman le Magnifique', 'Bayezid Ier', 'Selim Ier'], 'fr', true, 'Mehmet II, dit le Conquérant, a pris Constantinople le 29 mai 1453.'),
('history', 3, 'Quelle bataille de 1066 a permis à Guillaume de conquérir l''Angleterre ?', 'La bataille d''Hastings', ARRAY['La bataille de Crécy', 'La bataille d''Azincourt', 'La bataille de Bouvines'], 'fr', true, 'Guillaume le Conquérant a vaincu Harold II à Hastings et est devenu roi d''Angleterre.'),
('history', 3, 'Quel philosophe a écrit « Le Prince » au XVIe siècle ?', 'Machiavel', ARRAY['Montesquieu', 'Hobbes', 'Locke'], 'fr', true, 'Nicolas Machiavel a écrit Le Prince en 1513, traité de philosophie politique sur le pouvoir.'),
('history', 3, 'En quelle année a eu lieu la Nuit de la Saint-Barthélemy ?', '1572', ARRAY['1562', ' 1598', '1585'], 'fr', true, 'Le massacre de la Saint-Barthélemy, le 24 août 1572, a tué des milliers de protestants en France.'),
('history', 3, 'Quel général carthaginois a remporté la bataille de Cannes ?', 'Hannibal Barca', ARRAY['Hamilcar Barca', 'Hasdrubal', 'Scipion l''Africain'], 'fr', true, 'Hannibal a infligé une défaite écrasante aux Romains à Cannes en 216 av. J.-C.'),
('history', 3, 'Quelle dynastie chinoise a construit la majorité de la Grande Muraille actuelle ?', 'La dynastie Ming', ARRAY['La dynastie Qin', 'La dynastie Han', 'La dynastie Tang'], 'fr', true, 'La Grande Muraille telle qu''on la connaît aujourd''hui a été largement reconstruite sous les Ming (1368-1644).'),
('history', 3, 'Qui a été le dernier tsar de Russie ?', 'Nicolas II', ARRAY['Alexandre III', 'Alexandre II', 'Pierre le Grand'], 'fr', true, 'Nicolas II a abdiqué en 1917 et a été exécuté avec sa famille en 1918.'),
('history', 3, 'Quel accord de 1938 a permis à Hitler d''annexer les Sudètes ?', 'Les accords de Munich', ARRAY['Le pacte germano-soviétique', 'Le traité de Versailles', 'L''Anschluss'], 'fr', true, 'Les accords de Munich, signés le 30 septembre 1938, sont devenus un symbole de l''appeasement.'),
('history', 3, 'Quelle reine d''Angleterre a régné pendant 63 ans au XIXe siècle ?', 'La reine Victoria', ARRAY['La reine Élisabeth Ire', 'La reine Anne', 'La reine Mary'], 'fr', true, 'La reine Victoria a régné de 1837 à 1901, donnant son nom à l''ère victorienne.'),
('history', 3, 'Quel navigateur a réalisé le premier tour du monde complet ?', 'Juan Sebastián Elcano', ARRAY['Magellan', 'Francis Drake', 'James Cook'], 'fr', true, 'Magellan est mort aux Philippines en 1521 ; c''est Elcano qui a achevé le tour du monde en 1522.'),
('history', 3, 'En quelle année la guerre de Crimée a-t-elle commencé ?', '1853', ARRAY['1848', '1860', '1870'], 'fr', true, 'La guerre de Crimée (1853-1856) opposa la Russie à une coalition menée par la France et le Royaume-Uni.'),
('history', 3, 'Quel empereur romain a divisé l''Empire en deux parties ?', 'Dioclétien', ARRAY['Constantin', 'Théodose', 'Auguste'], 'fr', true, 'Dioclétien a instauré la tétrarchie en 293, divisant l''Empire romain en parties orientale et occidentale.'),
('history', 3, 'Quelle bataille de 1916 est l''une des plus meurtrières de la Grande Guerre ?', 'La bataille de Verdun', ARRAY['La bataille de la Somme', 'La bataille de la Marne', 'La bataille de Gallipoli'], 'fr', true, 'La bataille de Verdun a duré de février à décembre 1916, faisant plus de 700 000 victimes.'),
('history', 3, 'Quel roi de Prusse a unifié l''Allemagne en 1871 ?', 'Guillaume Ier', ARRAY['Frédéric II', 'Bismarck', 'Guillaume II'], 'fr', true, 'Guillaume Ier a été proclamé empereur allemand à Versailles le 18 janvier 1871.'),
('history', 3, 'Quel explorateur a découvert le fleuve Saint-Laurent au Canada ?', 'Jacques Cartier', ARRAY['Samuel de Champlain', 'La Salle', 'Cavelier de La Salle'], 'fr', true, 'Jacques Cartier a exploré le fleuve Saint-Laurent en 1534-1535 pour le compte de François Ier.'),
('history', 3, 'Quelle organisation internationale a été créée après la Première Guerre mondiale ?', 'La Société des Nations', ARRAY['L''ONU', 'L''OTAN', 'L''Union européenne'], 'fr', true, 'La Société des Nations, créée en 1920, était le précurseur de l''ONU.'),
('history', 3, 'Qui a été le premier empereur de Chine ?', 'Qin Shi Huang', ARRAY['Liu Bang', 'Wu Zetian', 'Kangxi'], 'fr', true, 'Qin Shi Huang a unifié la Chine en 221 av. J.-C. et a commencé la construction de la Grande Muraille.'),
('history', 3, 'Quel événement a marqué le début de la Réforme protestante en 1517 ?', 'Les 95 thèses de Martin Luther', ARRAY['Le concile de Trente', 'L''édit de Nantes', 'Le schisme d''Orient'], 'fr', true, 'Martin Luther a affiché ses 95 thèses sur la porte de l''église de Wittenberg le 31 octobre 1517.'),
('history', 3, 'Quelle civilisation a développé l''écriture cunéiforme ?', 'Les Sumériens', ARRAY['Les Égyptiens', 'Les Phéniciens', 'Les Hittites'], 'fr', true, 'L''écriture cunéiforme, inventée vers 3400 av. J.-C. en Mésopotamie, est l''une des plus anciennes écritures.'),
('history', 3, 'Quel roi de France a été surnommé le Bien-Aimé ?', 'Louis XV', ARRAY['Louis XIV', 'Louis XVI', 'Henri IV'], 'fr', true, 'Louis XV (1715-1774) fut surnommé le Bien-Aimé au début de son règne, avant de perdre sa popularité.'),
('history', 3, 'Quelle conférence de 1945 a réorganisé l''Europe d''après-guerre ?', 'La conférence de Yalta', ARRAY['La conférence de Potsdam', 'La conférence de Téhéran', 'La conférence de Casablanca'], 'fr', true, 'La conférence de Yalta, en février 1945, a réuni Roosevelt, Churchill et Staline.'),
('history', 3, 'En quelle année l''Empire romain d''Occident a-t-il chuté ?', '476', ARRAY['410', '455', '500'], 'fr', true, 'La déposition de Romulus Augustule en 476 marque la fin de l''Empire romain d''Occident.'),
('history', 3, 'Quel scientifique a découvert la radioactivité ?', 'Henri Becquerel', ARRAY['Marie Curie', 'Pierre Curie', 'Ernest Rutherford'], 'fr', true, 'Henri Becquerel a découvert la radioactivité en 1896 en travaillant sur l''uranium.'),
('history', 3, 'Quelle guerre civile espagnole a duré de 1936 à 1939 ?', 'La Guerre civile espagnole', ARRAY['La Guerre d''indépendance espagnole', 'La Reconquista', 'La Guerre carliste'], 'fr', true, 'La Guerre civile espagnole opposa les républicains aux nationalistes de Franco.'),
('history', 3, 'Quel peuple a construit la cité perdue du Machu Picchu ?', 'Les Incas', ARRAY['Les Mayas', 'Les Aztèques', 'Les Mochicas'], 'fr', true, 'Le Machu Picchu a été construit par les Incas au XVe siècle dans les Andes péruviennes.'),
('history', 3, 'Qui a été le premier chancelier de l''Allemagne unifiée en 1871 ?', 'Otto von Bismarck', ARRAY['Guillaume Ier', 'Helmut Kohl', 'Friedrich Ebert'], 'fr', true, 'Bismarck, surnommé le Chancelier de fer, a orchestré l''unification allemande.'),
('history', 3, 'Quelle révolution a renversé le régime tsariste en Russie ?', 'La révolution d''Octobre 1917', ARRAY['La révolution de 1905', 'La révolution de Février 1917', 'Le coup d''État de 1991'], 'fr', true, 'La révolution d''Octobre 1917, menée par les bolcheviks, a instauré le régime soviétique.'),
('history', 3, 'Quel traité de 1494 a partagé le Nouveau Monde entre l''Espagne et le Portugal ?', 'Le traité de Tordesillas', ARRAY['Le traité de Westphalie', 'Le traité de Paris', 'Le traité de Saragosse'], 'fr', true, 'Le traité de Tordesillas a divisé les terres nouvellement découvertes entre les deux puissances ibériques.'),
('history', 3, 'Qui a fondé la ville de Saint-Pétersbourg ?', 'Pierre le Grand', ARRAY['Catherine II', 'Ivan le Terrible', 'Alexandre Ier'], 'fr', true, 'Pierre le Grand a fondé Saint-Pétersbourg en 1703 pour en faire la nouvelle capitale de la Russie.'),
('history', 3, 'Quelle guerre a opposé la France et la Prusse en 1870-1871 ?', 'La guerre franco-prussienne', ARRAY['La guerre de Sept Ans', 'La guerre de Trente Ans', 'La guerre de Succession d''Espagne'], 'fr', true, 'La défaite française a conduit à la chute de Napoléon III et à la proclamation de la IIIe République.'),
('history', 3, 'Quel savant a développé la théorie de l''évolution par sélection naturelle ?', 'Charles Darwin', ARRAY['Jean-Baptiste Lamarck', 'Gregor Mendel', 'Alfred Wallace'], 'fr', true, 'Charles Darwin a publié L''Origine des espèces en 1859, révolutionnant la biologie.'),
('history', 3, 'En quelle année l''Inde a-t-elle obtenu son indépendance ?', '1947', ARRAY['1945', '1950', '1942'], 'fr', true, 'L''Inde est devenue indépendante du Royaume-Uni le 15 août 1947.'),
('history', 3, 'Quel roi carolingien a été couronné empereur en l''an 800 ?', 'Charlemagne', ARRAY['Pépin le Bref', 'Louis le Pieux', 'Charles le Chauve'], 'fr', true, 'Charlemagne a été couronné empereur par le pape Léon III à Rome le 25 décembre 800.'),
('history', 3, 'Quelle crise de 1962 a failli déclencher une guerre nucléaire ?', 'La crise des missiles de Cuba', ARRAY['La crise de Berlin', 'La crise de Suez', 'La guerre de Corée'], 'fr', true, 'La crise des missiles de Cuba en octobre 1962 a opposé les États-Unis et l''URSS pendant 13 jours.'),
('history', 3, 'Quel architecte a conçu les jardins de Versailles ?', 'André Le Nôtre', ARRAY['Jules Hardouin-Mansart', 'Le Vau', 'Charles Perrault'], 'fr', true, 'André Le Nôtre a créé les jardins à la française de Versailles pour Louis XIV.'),
('history', 3, 'Qui a dirigé la résistance contre les nazis à partir de Londres ?', 'Charles de Gaulle', ARRAY['Jean Moulin', 'Philippe Pétain', 'Pierre Laval'], 'fr', true, 'Le général de Gaulle a lancé l''appel du 18 juin 1940 depuis Londres.'),
('history', 3, 'Quelle civilisation a inventé le papyrus ?', 'Les Égyptiens', ARRAY['Les Grecs', 'Les Romains', 'Les Chinois'], 'fr', true, 'Les Égyptiens ont inventé le papyrus vers 3000 av. J.-C. à partir de la plante du même nom.'),
('history', 3, 'Quel congrès de 1814-1815 a redessiné les frontières européennes ?', 'Le congrès de Vienne', ARRAY['Le congrès de Berlin', 'Le congrès de Paris', 'Le congrès de Westphalie'], 'fr', true, 'Le congrès de Vienne a rétabli l''équilibre des puissances européennes après les guerres napoléoniennes.'),
('history', 3, 'Quelle île grecque est célèbre pour la civilisation minoenne ?', 'La Crète', ARRAY['Rhodes', 'Corfou', 'Santorin'], 'fr', true, 'La civilisation minoenne s''est développée en Crète de 2700 à 1450 av. J.-C.'),
('history', 3, 'En quelle année le canal de Suez a-t-il été inauguré ?', '1869', ARRAY['1856', '1878', '1882'], 'fr', true, 'Le canal de Suez, construit par Ferdinand de Lesseps, a été inauguré le 17 novembre 1869.'),
('history', 3, 'Quel peuple germanique a saccagé Rome en 410 ?', 'Les Wisigoths', ARRAY['Les Vandales', 'Les Ostrogoths', 'Les Huns'], 'fr', true, 'Le roi wisigoth Alaric Ier a mis Rome à sac en 410, choquant tout l''Empire romain.'),
('history', 3, 'Quelle guerre a opposé les forces communistes et anticommunistes en Corée ?', 'La guerre de Corée', ARRAY['La guerre du Vietnam', 'La guerre froide', 'La guerre sino-japonaise'], 'fr', true, 'La guerre de Corée (1950-1953) a divisé la péninsule en Corée du Nord et Corée du Sud.'),
('history', 3, 'Qui a écrit l''Encyclopédie au XVIIIe siècle ?', 'Diderot et d''Alembert', ARRAY['Voltaire et Rousseau', 'Montesquieu et Condorcet', 'Descartes et Pascal'], 'fr', true, 'L''Encyclopédie, dirigée par Diderot et d''Alembert, a été publiée entre 1751 et 1772.'),
('history', 3, 'Quelle bataille de 732 a stoppé l''avancée arabe en Europe ?', 'La bataille de Poitiers', ARRAY['La bataille de Tours', 'La bataille de Roncevaux', 'La bataille de Vouillé'], 'fr', true, 'Charles Martel a repoussé les forces omeyyades à Poitiers en 732.');
