('history', 4, 'Quel souverain a régné sur le Saint-Empire romain germanique sous le nom de Charles Quint ?', 'Charles de Habsbourg', ARRAY['Charles de Bourbon', 'Charles de Valois', 'Charles de Luxembourg'], 'fr', true, 'Charles Quint a régné sur un empire où le soleil ne se couchait jamais, de 1519 à 1556.'),
('history', 4, 'Quelle conférence de 1884-1885 a décidé du partage de l''Afrique ?', 'La conférence de Berlin', ARRAY['La conférence de Vienne', 'La conférence de Paris', 'La conférence de Bruxelles'], 'fr', true, 'La conférence de Berlin a fixé les règles de la colonisation européenne de l''Afrique.'),
('history', 4, 'Quel philosophe grec a été le précepteur d''Alexandre le Grand ?', 'Aristote', ARRAY['Platon', 'Socrate', 'Diogène'], 'fr', true, 'Aristote a enseigné à Alexandre le Grand de 343 à 340 av. J.-C. en Macédoine.'),
('history', 4, 'Quelle bataille de 1346 a vu la victoire anglaise grâce aux archers ?', 'La bataille de Crécy', ARRAY['La bataille d''Azincourt', 'La bataille de Poitiers', 'La bataille de Bouvines'], 'fr', true, 'Les archers anglais avec leurs arcs longs ont décimé la chevalerie française à Crécy.'),
('history', 4, 'En quelle année le Japon a-t-il ouvert ses ports aux Occidentaux ?', '1854', ARRAY['1868', '1853', '1867'], 'fr', true, 'Le commodore Perry a forcé le Japon à ouvrir ses ports par la convention de Kanagawa en 1854.'),
('history', 4, 'Quel général romain a franchi le Rubicon en 49 av. J.-C. ?', 'Jules César', ARRAY['Pompée', 'Crassus', 'Brutus'], 'fr', true, 'César a franchi le Rubicon avec ses légions, déclenchant la guerre civile romaine.'),
('history', 4, 'Quelle révolution de 1830 a renversé Charles X en France ?', 'Les Trois Glorieuses', ARRAY['La Commune de Paris', 'La Fronde', 'Le coup d''État du 18 Brumaire'], 'fr', true, 'Les journées révolutionnaires des 27, 28 et 29 juillet 1830 ont porté Louis-Philippe au pouvoir.'),
('history', 4, 'Quel peuple a fondé l''Empire du Mali au XIIIe siècle ?', 'Les Mandingues', ARRAY['Les Songhaïs', 'Les Peuls', 'Les Haoussas'], 'fr', true, 'L''Empire du Mali, fondé par Soundiata Keïta vers 1235, devint l''un des plus puissants d''Afrique.'),
('history', 4, 'Quelle bataille navale de 480 av. J.-C. a sauvé la Grèce de l''invasion perse ?', 'La bataille de Salamine', ARRAY['La bataille de Marathon', 'La bataille de Platées', 'La bataille de Mycale'], 'fr', true, 'Thémistocle a mené la flotte athénienne à la victoire contre les Perses à Salamine.'),
('history', 4, 'Quel empire africain était dirigé par Mansa Moussa au XIVe siècle ?', 'L''Empire du Mali', ARRAY['L''Empire songhaï', 'Le Royaume du Ghana', 'Le Royaume du Kongo'], 'fr', true, 'Mansa Moussa est considéré comme l''homme le plus riche de l''histoire grâce à l''or du Mali.'),
('history', 4, 'Quelle conspiration a tenté de faire sauter le Parlement anglais en 1605 ?', 'La Conspiration des Poudres', ARRAY['La Conspiration de Babington', 'Le complot de Ridolfi', 'La Conspiration de Throckmorton'], 'fr', true, 'Guy Fawkes a été arrêté le 5 novembre 1605 alors qu''il tentait de faire sauter le Parlement.'),
('history', 4, 'Quel mouvement intellectuel du XIVe siècle a précédé la Renaissance ?', 'L''humanisme', ARRAY['Le rationalisme', 'Le positivisme', 'Le stoïcisme'], 'fr', true, 'L''humanisme, initié par Pétrarque, a replacé l''homme au centre de la réflexion intellectuelle.'),
('history', 4, 'En quelle année le Code d''Hammurabi a-t-il été rédigé ?', 'Vers 1750 av. J.-C.', ARRAY['Vers 2500 av. J.-C.', 'Vers 1000 av. J.-C.', 'Vers 500 av. J.-C.'], 'fr', true, 'Le Code d''Hammurabi est l''un des plus anciens textes de lois connus, gravé à Babylone.'),
('history', 4, 'Quelle dynastie a fondé l''Empire ottoman ?', 'La dynastie osmanli', ARRAY['La dynastie seldjoukide', 'La dynastie abbasside', 'La dynastie safavide'], 'fr', true, 'Osman Ier a fondé la dynastie ottomane vers 1299 en Anatolie.'),
('history', 4, 'Quel roi de France a remporté la bataille de Marignan en 1515 ?', 'François Ier', ARRAY['Louis XII', 'Henri II', 'Charles VIII'], 'fr', true, 'François Ier a vaincu les Suisses à Marignan le 13-14 septembre 1515.'),
('history', 4, 'Quelle peste a décimé un tiers de la population européenne au XIVe siècle ?', 'La Peste noire', ARRAY['La peste de Justinien', 'La grande peste de Londres', 'La peste de Marseille'], 'fr', true, 'La Peste noire (1347-1352) a tué environ 25 millions de personnes en Europe.'),
('history', 4, 'Quel traité de 1919 a redessiné les frontières de l''Empire ottoman ?', 'Le traité de Sèvres', ARRAY['Le traité de Lausanne', 'Le traité de Versailles', 'Le traité de Saint-Germain'], 'fr', true, 'Le traité de Sèvres a démantelé l''Empire ottoman, mais fut révisé par le traité de Lausanne en 1923.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 5, 'Quel était le nom de l''épée de Charlemagne ?', 'Joyeuse', ARRAY['Durandal', 'Excalibur', 'Hauteclaire'], 'fr', true, 'Joyeuse est l''épée légendaire de Charlemagne, mentionnée dans la Chanson de Roland.'),
