('history', 5, 'Quel empereur romain a construit le mur séparant l''Angleterre de l''Écosse ?', 'Hadrien', ARRAY['Trajan', 'Marc Aurèle', 'Antonin le Pieux'], 'fr', true, 'Le mur d''Hadrien, construit vers 122 apr. J.-C., marquait la frontière nord de l''Empire romain.'),
('history', 5, 'Quelle bataille de 1757 est considérée comme le chef-d''œuvre tactique de Frédéric II ?', 'La bataille de Leuthen', ARRAY['La bataille de Rossbach', 'La bataille de Zorndorf', 'La bataille de Kunersdorf'], 'fr', true, 'Frédéric II de Prusse a vaincu les Autrichiens à Leuthen grâce à un ordre oblique brillant.'),
('history', 5, 'Quel calife abbasside a fondé la ville de Bagdad ?', 'Al-Mansur', ARRAY['Haroun al-Rachid', 'Al-Mamoun', 'Al-Mutasim'], 'fr', true, 'Le calife Al-Mansur a fondé Bagdad en 762 pour en faire la capitale abbasside.'),
('history', 5, 'Comment s''appelait le premier code de lois connu de l''histoire ?', 'Le Code d''Ur-Nammu', ARRAY['Le Code d''Hammurabi', 'Les Lois de Manu', 'Les Douze Tables'], 'fr', true, 'Le Code d''Ur-Nammu, rédigé vers 2100 av. J.-C. à Sumer, précède le Code d''Hammurabi.'),
('history', 5, 'Quel roi wisigoth a mis fin à l''Empire romain d''Occident ?', 'Odoacre', ARRAY['Alaric', 'Théodoric', 'Genséric'], 'fr', true, 'Odoacre, chef barbare, a déposé le dernier empereur Romulus Augustule en 476.'),
('history', 5, 'Quelle dynastie perse a régné de 224 à 651 ?', 'Les Sassanides', ARRAY['Les Achéménides', 'Les Séleucides', 'Les Parthes'], 'fr', true, 'L''Empire sassanide fut le dernier grand empire perse avant la conquête arabe.'),
('history', 5, 'Quel général a vaincu les Maures à la bataille de Las Navas de Tolosa en 1212 ?', 'Alphonse VIII de Castille', ARRAY['Ferdinand III', 'Rodrigo Díaz de Vivar', 'Jacques Ier d''Aragon'], 'fr', true, 'Cette bataille est considérée comme le tournant de la Reconquista en Espagne.'),
('history', 5, 'En quelle année le concile de Nicée a-t-il eu lieu ?', '325', ARRAY['381', '451', '787'], 'fr', true, 'Le premier concile de Nicée, convoqué par Constantin en 325, a défini les bases du dogme chrétien.'),
('history', 5, 'Quel souverain moghol a fait construire le Taj Mahal ?', 'Shah Jahan', ARRAY['Akbar', 'Aurangzeb', 'Babur'], 'fr', true, 'Shah Jahan a fait bâtir le Taj Mahal entre 1632 et 1653 en mémoire de son épouse Mumtaz Mahal.'),
('history', 5, 'Quelle bataille de 1683 a marqué le début du déclin ottoman en Europe ?', 'Le siège de Vienne', ARRAY['La bataille de Lépante', 'La bataille de Mohács', 'La bataille de Zenta'], 'fr', true, 'L''échec du siège de Vienne en 1683 marqua le début du recul ottoman en Europe.'),
('history', 5, 'Quel traité de 1648 a reconnu l''indépendance des Provinces-Unies ?', 'La paix de Münster', ARRAY['Le traité d''Utrecht', 'Le traité de Breda', 'Le traité de La Haye'], 'fr', true, 'La paix de Münster, partie des traités de Westphalie, a reconnu l''indépendance néerlandaise.'),
('history', 5, 'Quel empereur chinois de la dynastie Tang est considéré comme le plus grand ?', 'Taizong', ARRAY['Xuanzong', 'Gaozu', 'Wu Zetian'], 'fr', true, 'L''empereur Taizong des Tang (626-649) est célébré pour avoir porté la Chine à son apogée.'),
('history', 5, 'Quelle révolte de 73 av. J.-C. a été menée par un gladiateur célèbre ?', 'La révolte de Spartacus', ARRAY['La révolte de Vercingétorix', 'La révolte de Boudicca', 'La révolte des Gracques'], 'fr', true, 'Spartacus a mené la troisième guerre servile contre Rome avec des dizaines de milliers d''esclaves.'),
('history', 5, 'Quel explorateur a atteint le pôle Sud en premier en 1911 ?', 'Roald Amundsen', ARRAY['Robert Scott', 'Ernest Shackleton', 'Richard Byrd'], 'fr', true, 'Le Norvégien Amundsen a atteint le pôle Sud le 14 décembre 1911, devançant Scott de cinq semaines.'),
('history', 5, 'Quelle dynastie a régné sur l''Éthiopie et prétendait descendre de Salomon ?', 'La dynastie salomonienne', ARRAY['La dynastie zagwé', 'La dynastie aksumite', 'La dynastie gondarine'], 'fr', true, 'La dynastie salomonienne a régné de 1270 à 1974, se proclamant descendante du roi Salomon.'),
('history', 5, 'Quel mathématicien grec a crié « Eurêka » dans son bain ?', 'Archimède', ARRAY['Euclide', 'Pythagore', 'Thalès'], 'fr', true, 'Archimède aurait découvert le principe de la poussée dans son bain à Syracuse au IIIe siècle av. J.-C.'),
('history', 5, 'Quel est le nom du parlement islandais, le plus ancien du monde ?', 'L''Althing', ARRAY['Le Folketing', 'Le Storting', 'Le Riksdag'], 'fr', true, 'L''Althing a été fondé en 930 à Thingvellir, faisant de l''Islande la plus ancienne démocratie parlementaire.'),
('history', 5, 'Quelle ville antique était la capitale de l''Empire assyrien ?', 'Ninive', ARRAY['Babylone', 'Ur', 'Persépolis'], 'fr', true, 'Ninive fut la capitale de l''Empire néo-assyrien et l''une des plus grandes villes du monde antique.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 1, 'Which ancient civilization built the Sphinx?', 'The Egyptians', ARRAY['The Greeks', 'The Romans', 'The Persians'], 'en', true, 'The Great Sphinx of Giza was built by the ancient Egyptians around 2500 BC.'),
('history', 1, 'Who was the first woman to fly solo across the Atlantic?', 'Amelia Earhart', ARRAY['Bessie Coleman', 'Harriet Quimby', 'Jacqueline Cochran'], 'en', true, 'Amelia Earhart completed her solo transatlantic flight in 1932.'),
('history', 1, 'What was the name of the ship that brought the Pilgrims to America?', 'The Mayflower', ARRAY['The Santa Maria', 'The Victoria', 'The Endeavour'], 'en', true, 'The Mayflower carried the Pilgrims from England to Plymouth, Massachusetts in 1620.'),
('history', 1, 'Which country built the Panama Canal?', 'The United States', ARRAY['France', 'Spain', 'Great Britain'], 'en', true, 'The US completed the Panama Canal in 1914 after France abandoned its earlier attempt.'),
('history', 1, 'Who was known as the Iron Lady?', 'Margaret Thatcher', ARRAY['Queen Victoria', 'Angela Merkel', 'Indira Gandhi'], 'en', true, 'Margaret Thatcher, British Prime Minister from 1979 to 1990, was called the Iron Lady.'),
('history', 1, 'What type of government did ancient Sparta have?', 'A military oligarchy', ARRAY['A democracy', 'A monarchy', 'A republic'], 'en', true, 'Sparta was ruled by two kings and a council of elders with a strong military focus.'),
('history', 1, 'Which empire was ruled by the Caesars?', 'The Roman Empire', ARRAY['The Greek Empire', 'The Persian Empire', 'The Ottoman Empire'], 'en', true, 'The Roman Empire was ruled by a series of emperors known as Caesars.'),
('history', 1, 'What did the ancient Romans use to count?', 'Roman numerals', ARRAY['Arabic numerals', 'Binary code', 'Tally marks'], 'en', true, 'Roman numerals use letters like I, V, X, L, C, D, and M to represent numbers.'),
('history', 1, 'Who painted the Mona Lisa?', 'Leonardo da Vinci', ARRAY['Michelangelo', 'Raphael', 'Rembrandt'], 'en', true, 'Leonardo da Vinci painted the Mona Lisa around 1503-1519 in Florence, Italy.'),
('history', 1, 'What ancient wonder was located in the city of Babylon?', 'The Hanging Gardens', ARRAY['The Colossus', 'The Lighthouse', 'The Great Pyramid'], 'en', true, 'The Hanging Gardens of Babylon were one of the Seven Wonders of the Ancient World.'),
('history', 1, 'Which civilization invented paper?', 'The Chinese', ARRAY['The Egyptians', 'The Romans', 'The Arabs'], 'en', true, 'Paper was invented in China around 105 AD by Cai Lun during the Han Dynasty.'),
('history', 1, 'Who was the famous nurse during the Crimean War?', 'Florence Nightingale', ARRAY['Clara Barton', 'Mary Seacole', 'Dorothea Dix'], 'en', true, 'Florence Nightingale revolutionized nursing care during the Crimean War in the 1850s.'),
('history', 1, 'What did the ancient Greeks call their city-states?', 'Polis', ARRAY['Province', 'County', 'District'], 'en', true, 'Greek city-states like Athens and Sparta were called polis (plural: poleis).'),
('history', 1, 'Which war was fought between the North and South of the United States?', 'The Civil War', ARRAY['The Revolutionary War', 'The War of 1812', 'World War I'], 'en', true, 'The American Civil War lasted from 1861 to 1865 over slavery and states'' rights.'),
('history', 1, 'Who discovered penicillin?', 'Alexander Fleming', ARRAY['Louis Pasteur', 'Joseph Lister', 'Edward Jenner'], 'en', true, 'Alexander Fleming accidentally discovered penicillin in 1928 from a mold culture.'),
('history', 1, 'What civilization built Machu Picchu?', 'The Incas', ARRAY['The Aztecs', 'The Mayas', 'The Olmecs'], 'en', true, 'The Incas built Machu Picchu in the 15th century high in the Andes Mountains of Peru.'),
('history', 1, 'Who was the first emperor of unified China?', 'Qin Shi Huang', ARRAY['Confucius', 'Kublai Khan', 'Sun Tzu'], 'en', true, 'Qin Shi Huang unified China in 221 BC and began construction of the Great Wall.'),
('history', 1, 'What was the Cold War?', 'A political rivalry between the US and USSR', ARRAY['A war fought in winter', 'A battle in Antarctica', 'A conflict in Siberia'], 'en', true, 'The Cold War was a geopolitical tension between the US and USSR from 1947 to 1991.'),
('history', 1, 'Which king of England signed the Magna Carta?', 'King John', ARRAY['King Henry VIII', 'King Richard I', 'King Edward I'], 'en', true, 'King John signed the Magna Carta at Runnymede in 1215 under pressure from the barons.'),
('history', 1, 'What ancient road connected Rome to southern Italy?', 'The Appian Way', ARRAY['The Silk Road', 'The Royal Road', 'The Via Flaminia'], 'en', true, 'The Appian Way, built in 312 BC, was one of the most important Roman roads.'),
('history', 1, 'Who led the French army at the Battle of Waterloo?', 'Napoleon Bonaparte', ARRAY['Louis XVIII', 'Marshal Ney', 'Duke of Wellington'], 'en', true, 'Napoleon led the French army at Waterloo in 1815, where he was defeated by Wellington and Blucher.'),
('history', 1, 'What event started World War I?', 'The assassination of Archduke Franz Ferdinand', ARRAY['The invasion of Poland', 'The sinking of the Lusitania', 'The Battle of the Marne'], 'en', true, 'The assassination in Sarajevo on June 28, 1914 triggered the chain of events leading to WWI.'),
('history', 1, 'Which explorer reached India by sailing around Africa?', 'Vasco da Gama', ARRAY['Christopher Columbus', 'Ferdinand Magellan', 'Marco Polo'], 'en', true, 'Vasco da Gama reached Calicut, India in 1498 by sailing around the Cape of Good Hope.'),
('history', 1, 'What was the purpose of medieval castles?', 'Defense and protection', ARRAY['Entertainment', 'Trade', 'Farming'], 'en', true, 'Medieval castles were fortified structures built for defense against invaders.'),
('history', 1, 'Who was the queen of Egypt who allied with Julius Caesar?', 'Cleopatra', ARRAY['Nefertiti', 'Hatshepsut', 'Isis'], 'en', true, 'Cleopatra VII allied with Julius Caesar and later Mark Antony against Rome.'),
('history', 1, 'What writing system did the ancient Mesopotamians use?', 'Cuneiform', ARRAY['Hieroglyphics', 'The alphabet', 'Runes'], 'en', true, 'Cuneiform, invented by the Sumerians around 3400 BC, used wedge-shaped marks on clay tablets.'),
('history', 1, 'Which country was the first to use gunpowder in warfare?', 'China', ARRAY['Japan', 'Turkey', 'India'], 'en', true, 'China invented gunpowder around the 9th century and used it in warfare by the 10th century.'),
('history', 1, 'Who wrote the Declaration of Independence?', 'Thomas Jefferson', ARRAY['Benjamin Franklin', 'George Washington', 'John Adams'], 'en', true, 'Thomas Jefferson was the principal author of the Declaration of Independence in 1776.'),
('history', 1, 'What is the oldest known civilization in the world?', 'Sumer', ARRAY['Egypt', 'China', 'India'], 'en', true, 'The Sumerian civilization in Mesopotamia dates back to around 4500 BC.'),
('history', 1, 'Which European country colonized most of South America?', 'Spain', ARRAY['Portugal', 'France', 'England'], 'en', true, 'Spain colonized most of Central and South America in the 16th century.'),
('history', 1, 'What was the Silk Road?', 'An ancient trade route between East and West', ARRAY['A type of fabric', 'A Roman highway', 'A river in China'], 'en', true, 'The Silk Road connected China to the Mediterranean, facilitating trade for over 1500 years.'),
('history', 1, 'Who was the leader of Nazi Germany?', 'Adolf Hitler', ARRAY['Benito Mussolini', 'Joseph Stalin', 'Francisco Franco'], 'en', true, 'Adolf Hitler led Nazi Germany from 1933 until his death in 1945.'),
('history', 1, 'What revolution took place in France in 1789?', 'The French Revolution', ARRAY['The Industrial Revolution', 'The American Revolution', 'The Glorious Revolution'], 'en', true, 'The French Revolution overthrew the monarchy and established a republic.'),
('history', 1, 'Which ancient people built longships and raided European coasts?', 'The Vikings', ARRAY['The Saxons', 'The Celts', 'The Franks'], 'en', true, 'The Vikings from Scandinavia raided and explored from the 8th to 11th centuries.'),
('history', 1, 'What material did medieval knights wear for protection?', 'Armor', ARRAY['Leather', 'Silk', 'Cotton'], 'en', true, 'Medieval knights wore suits of metal armor for protection in battle.'),
('history', 1, 'Who invented the printing press in Europe?', 'Johannes Gutenberg', ARRAY['Leonardo da Vinci', 'Galileo Galilei', 'Isaac Newton'], 'en', true, 'Gutenberg invented the movable-type printing press around 1440 in Mainz, Germany.'),
('history', 1, 'What ancient structure was built to protect China from invaders?', 'The Great Wall of China', ARRAY['The Terracotta Army', 'The Forbidden City', 'The Grand Canal'], 'en', true, 'The Great Wall of China stretches over 20,000 km and was built over many centuries.'),
('history', 1, 'Who was the Greek god of the sea?', 'Poseidon', ARRAY['Zeus', 'Hades', 'Ares'], 'en', true, 'Poseidon was the Greek god of the sea, earthquakes, and horses.'),
('history', 1, 'What empire did Genghis Khan found?', 'The Mongol Empire', ARRAY['The Ottoman Empire', 'The Persian Empire', 'The Roman Empire'], 'en', true, 'Genghis Khan united the Mongol tribes and created the largest contiguous land empire in history.'),
('history', 1, 'Which country launched the first satellite into space?', 'The Soviet Union', ARRAY['The United States', 'China', 'France'], 'en', true, 'The USSR launched Sputnik, the first artificial satellite, on October 4, 1957.'),
('history', 1, 'What was the Renaissance?', 'A cultural rebirth in Europe', ARRAY['A military campaign', 'A religious movement', 'A type of government'], 'en', true, 'The Renaissance was a period of cultural and intellectual rebirth that began in Italy in the 14th century.'),
('history', 1, 'Who was Nelson Mandela?', 'South Africa''s first Black president', ARRAY['A famous explorer', 'A military general', 'A religious leader'], 'en', true, 'Nelson Mandela fought against apartheid and became South Africa''s president in 1994.'),
('history', 1, 'What was the Black Death?', 'A devastating plague in the 14th century', ARRAY['A volcanic eruption', 'A great famine', 'A major war'], 'en', true, 'The Black Death killed about one-third of Europe''s population between 1347 and 1352.'),
('history', 1, 'Which country gifted the Statue of Liberty to the United States?', 'France', ARRAY['England', 'Spain', 'Italy'], 'en', true, 'France gifted the Statue of Liberty to the US in 1886 as a symbol of friendship.'),
('history', 1, 'Who was the first person to circumnavigate the globe?', 'Ferdinand Magellan''s expedition', ARRAY['Christopher Columbus', 'James Cook', 'Francis Drake'], 'en', true, 'Magellan''s expedition completed the first circumnavigation in 1522, though Magellan died en route.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 2, 'What treaty ended World War I?', 'The Treaty of Versailles', ARRAY['The Treaty of Paris', 'The Treaty of Ghent', 'The Treaty of Vienna'], 'en', true, 'The Treaty of Versailles was signed on June 28, 1919, imposing harsh terms on Germany.'),
('history', 2, 'Who was the last pharaoh of Egypt?', 'Cleopatra VII', ARRAY['Ramesses II', 'Tutankhamun', 'Nefertiti'], 'en', true, 'Cleopatra VII was the last active ruler of the Ptolemaic Kingdom of Egypt.'),
('history', 2, 'In what year did the Berlin Wall fall?', '1989', ARRAY['1991', '1987', '1985'], 'en', true, 'The Berlin Wall fell on November 9, 1989, symbolizing the end of the Cold War.'),
('history', 2, 'Who led the Indian independence movement through nonviolence?', 'Mahatma Gandhi', ARRAY['Jawaharlal Nehru', 'Subhas Chandra Bose', 'B.R. Ambedkar'], 'en', true, 'Gandhi used civil disobedience and nonviolent protest to lead India to independence in 1947.'),
('history', 2, 'What was the Manhattan Project?', 'The US program to develop atomic bombs', ARRAY['A city planning project', 'A space exploration mission', 'A secret spy operation'], 'en', true, 'The Manhattan Project produced the first nuclear weapons during World War II.'),
('history', 2, 'Which dynasty built most of the Great Wall of China as we know it?', 'The Ming Dynasty', ARRAY['The Qin Dynasty', 'The Han Dynasty', 'The Tang Dynasty'], 'en', true, 'The Ming Dynasty (1368-1644) rebuilt and extended most of the Great Wall that stands today.'),
('history', 2, 'What was the main cause of the Hundred Years'' War?', 'Disputes over the French throne', ARRAY['Religious differences', 'Trade disputes', 'Colonial rivalry'], 'en', true, 'The Hundred Years'' War (1337-1453) was primarily over English claims to the French crown.'),
('history', 2, 'Who founded the Mongol Empire?', 'Genghis Khan', ARRAY['Kublai Khan', 'Tamerlane', 'Attila the Hun'], 'en', true, 'Genghis Khan united the Mongol tribes and founded the largest contiguous land empire in history.'),
('history', 2, 'What was the Protestant Reformation?', 'A religious movement that split Christianity in Europe', ARRAY['A political revolution', 'An economic reform', 'A cultural movement'], 'en', true, 'The Protestant Reformation began in 1517 when Martin Luther posted his 95 Theses.'),
('history', 2, 'Which battle is considered Napoleon''s greatest victory?', 'The Battle of Austerlitz', ARRAY['The Battle of Waterloo', 'The Battle of Jena', 'The Battle of Borodino'], 'en', true, 'The Battle of Austerlitz in 1805, also known as the Battle of the Three Emperors.'),
('history', 2, 'Who was the first person to reach the South Pole?', 'Roald Amundsen', ARRAY['Robert Scott', 'Ernest Shackleton', 'Richard Byrd'], 'en', true, 'Norwegian explorer Roald Amundsen reached the South Pole on December 14, 1911.'),
('history', 2, 'What civilization built the city of Tenochtitlan?', 'The Aztecs', ARRAY['The Mayas', 'The Incas', 'The Olmecs'], 'en', true, 'Tenochtitlan, founded in 1325, was the capital of the Aztec Empire on the site of modern Mexico City.'),
('history', 2, 'In what year did Japan attack Pearl Harbor?', '1941', ARRAY['1939', '1942', '1940'], 'en', true, 'Japan attacked Pearl Harbor on December 7, 1941, bringing the US into World War II.'),
('history', 2, 'Who was the first female ruler of England?', 'Mary I', ARRAY['Elizabeth I', 'Queen Victoria', 'Anne Boleyn'], 'en', true, 'Mary I became the first queen regnant of England in 1553.'),
('history', 2, 'What was the Age of Enlightenment?', 'An intellectual movement in the 18th century', ARRAY['A religious revival', 'A period of exploration', 'A technological revolution'], 'en', true, 'The Enlightenment emphasized reason, science, and individual rights in the 18th century.'),
('history', 2, 'Which empire controlled most of Southeast Europe for centuries?', 'The Ottoman Empire', ARRAY['The Byzantine Empire', 'The Russian Empire', 'The Habsburg Empire'], 'en', true, 'The Ottoman Empire controlled much of Southeast Europe from the 14th to the 20th century.'),
('history', 2, 'Who painted the ceiling of the Sistine Chapel?', 'Michelangelo', ARRAY['Leonardo da Vinci', 'Raphael', 'Botticelli'], 'en', true, 'Michelangelo painted the Sistine Chapel ceiling between 1508 and 1512 in the Vatican.'),
('history', 2, 'What caused the fall of the Roman Empire?', 'A combination of invasions, economic troubles, and internal decay', ARRAY['A single decisive battle', 'A natural disaster', 'A plague alone'], 'en', true, 'The Western Roman Empire fell in 476 AD due to multiple factors including barbarian invasions.'),
('history', 2, 'Who was the last Tsar of Russia?', 'Nicholas II', ARRAY['Alexander III', 'Peter the Great', 'Ivan the Terrible'], 'en', true, 'Nicholas II abdicated in 1917 and was executed with his family in 1918.'),
('history', 2, 'What was the Industrial Revolution?', 'A period of major technological and economic change starting in Britain', ARRAY['A political uprising', 'A religious reformation', 'A military campaign'], 'en', true, 'The Industrial Revolution began in Britain around 1760 with the invention of the steam engine.'),
('history', 2, 'Which ancient Greek philosopher taught Alexander the Great?', 'Aristotle', ARRAY['Plato', 'Socrates', 'Diogenes'], 'en', true, 'Aristotle tutored young Alexander from 343 to 340 BC in Macedonia.'),
('history', 2, 'What island was Napoleon exiled to after Waterloo?', 'Saint Helena', ARRAY['Elba', 'Corsica', 'Sardinia'], 'en', true, 'Napoleon was exiled to Saint Helena in 1815, where he died in 1821.'),
('history', 2, 'Who was Joan of Arc?', 'A French heroine of the Hundred Years'' War', ARRAY['A queen of France', 'An English spy', 'A Roman goddess'], 'en', true, 'Joan of Arc led French forces against the English and was burned at the stake in 1431.'),
('history', 2, 'What event triggered the start of World War II in Europe?', 'Germany''s invasion of Poland', ARRAY['The attack on Pearl Harbor', 'The annexation of Austria', 'The invasion of France'], 'en', true, 'Germany invaded Poland on September 1, 1939, prompting Britain and France to declare war.'),
('history', 2, 'Which ancient wonder was a giant statue on the island of Rhodes?', 'The Colossus of Rhodes', ARRAY['The Statue of Zeus', 'The Lighthouse of Alexandria', 'The Hanging Gardens'], 'en', true, 'The Colossus of Rhodes was a massive bronze statue built around 280 BC.'),
('history', 2, 'Who was the founder of the Ottoman Empire?', 'Osman I', ARRAY['Mehmet II', 'Suleiman the Magnificent', 'Bayezid I'], 'en', true, 'Osman I founded the Ottoman dynasty around 1299 in Anatolia.'),
('history', 2, 'What was the Reconquista?', 'The Christian reconquest of the Iberian Peninsula', ARRAY['A crusade to Jerusalem', 'A Viking invasion', 'A Roman military campaign'], 'en', true, 'The Reconquista lasted from 722 to 1492 when Granada fell to Ferdinand and Isabella.'),
('history', 2, 'Who established the first permanent English settlement in America?', 'The Jamestown colonists', ARRAY['The Pilgrims', 'The Puritans', 'Sir Walter Raleigh'], 'en', true, 'Jamestown, Virginia was established in 1607 as the first permanent English settlement.'),
('history', 2, 'What was the main goal of the Crusades?', 'To reclaim the Holy Land from Muslim control', ARRAY['To explore new continents', 'To spread democracy', 'To find trade routes'], 'en', true, 'The Crusades were a series of religious wars from 1096 to 1291 to control Jerusalem.'),
('history', 2, 'Who was the Sun King?', 'Louis XIV of France', ARRAY['Louis XVI', 'Henry VIII', 'Philip II of Spain'], 'en', true, 'Louis XIV was called the Sun King and built the Palace of Versailles during his long reign.'),
('history', 2, 'In what year did the atomic bombs fall on Japan?', '1945', ARRAY['1944', '1946', '1943'], 'en', true, 'The US dropped atomic bombs on Hiroshima and Nagasaki in August 1945.'),
('history', 2, 'What country was divided at the 38th parallel after WWII?', 'Korea', ARRAY['Vietnam', 'Germany', 'China'], 'en', true, 'Korea was divided into North and South at the 38th parallel in 1945.'),
('history', 2, 'Who led the Free French Forces during World War II?', 'Charles de Gaulle', ARRAY['Philippe Pétain', 'Jean Moulin', 'Pierre Laval'], 'en', true, 'Charles de Gaulle led the Free French from London after the fall of France in 1940.'),
('history', 2, 'What ancient civilization built ziggurats?', 'The Mesopotamians', ARRAY['The Egyptians', 'The Greeks', 'The Chinese'], 'en', true, 'Ziggurats were massive stepped temples built by the Sumerians, Babylonians, and Assyrians.'),
('history', 2, 'Who was Spartacus?', 'A gladiator who led a slave revolt against Rome', ARRAY['A Roman emperor', 'A Greek philosopher', 'A Carthaginian general'], 'en', true, 'Spartacus led the Third Servile War against Rome from 73 to 71 BC.'),
('history', 2, 'What country did the Bolshevik Revolution take place in?', 'Russia', ARRAY['France', 'China', 'Germany'], 'en', true, 'The Bolshevik Revolution of October 1917 established Soviet communist rule in Russia.'),
('history', 2, 'Which explorer sailed for Spain and reached the Caribbean in 1492?', 'Christopher Columbus', ARRAY['Vasco da Gama', 'Ferdinand Magellan', 'John Cabot'], 'en', true, 'Columbus reached the Bahamas on October 12, 1492, believing he had reached Asia.'),
('history', 2, 'What was the Reign of Terror?', 'A period of extreme violence during the French Revolution', ARRAY['A medieval plague', 'A Roman persecution', 'A colonial war'], 'en', true, 'The Reign of Terror (1793-1794) saw mass executions led by Robespierre in France.'),
('history', 2, 'Who built the Taj Mahal?', 'Shah Jahan', ARRAY['Akbar', 'Aurangzeb', 'Babur'], 'en', true, 'Mughal emperor Shah Jahan built the Taj Mahal between 1632 and 1653 for his wife Mumtaz Mahal.'),
('history', 2, 'What was the significance of the Rosetta Stone?', 'It helped decipher Egyptian hieroglyphics', ARRAY['It contained a treasure map', 'It was a religious text', 'It recorded Roman laws'], 'en', true, 'The Rosetta Stone, found in 1799, allowed Champollion to decode hieroglyphics in 1822.'),
('history', 2, 'Which war was fought in the trenches of France and Belgium?', 'World War I', ARRAY['World War II', 'The Franco-Prussian War', 'The Napoleonic Wars'], 'en', true, 'WWI featured extensive trench warfare on the Western Front from 1914 to 1918.'),
('history', 2, 'Who was the first president of the Fifth French Republic?', 'Charles de Gaulle', ARRAY['François Mitterrand', 'Georges Pompidou', 'René Coty'], 'en', true, 'De Gaulle founded the Fifth Republic in 1958 and served as its first president.'),
('history', 2, 'What people built the ancient city of Carthage?', 'The Phoenicians', ARRAY['The Greeks', 'The Romans', 'The Berbers'], 'en', true, 'Phoenician traders from Tyre founded Carthage around 814 BC in modern-day Tunisia.'),
('history', 2, 'What was apartheid?', 'A system of racial segregation in South Africa', ARRAY['A form of government', 'A military strategy', 'A trade agreement'], 'en', true, 'Apartheid was a policy of racial segregation enforced in South Africa from 1948 to 1991.'),
('history', 2, 'In what year did India gain independence from Britain?', '1947', ARRAY['1945', '1950', '1942'], 'en', true, 'India achieved independence on August 15, 1947, after decades of nonviolent resistance.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 3, 'What treaty ended the Thirty Years'' War in 1648?', 'The Peace of Westphalia', ARRAY['The Treaty of Utrecht', 'The Treaty of Tordesillas', 'The Treaty of Vienna'], 'en', true, 'The Peace of Westphalia established the principle of state sovereignty in Europe.'),
('history', 3, 'Who was the Byzantine emperor when Constantinople fell in 1453?', 'Constantine XI', ARRAY['Justinian I', 'Basil II', 'Alexios I'], 'en', true, 'Constantine XI Palaiologos was the last Byzantine emperor, dying during the Ottoman siege.'),
('history', 3, 'What was the Edict of Nantes?', 'A decree granting religious tolerance to French Protestants', ARRAY['A trade agreement', 'A declaration of war', 'A peace treaty'], 'en', true, 'Henry IV of France signed the Edict of Nantes in 1598 to end the Wars of Religion.'),
('history', 3, 'Who led the Norman conquest of England in 1066?', 'William the Conqueror', ARRAY['Harold Godwinson', 'Edward the Confessor', 'Charlemagne'], 'en', true, 'William of Normandy defeated Harold II at the Battle of Hastings and became king.'),
('history', 3, 'What was the Meiji Restoration?', 'The modernization of Japan in 1868', ARRAY['A Chinese reform', 'A Korean revolution', 'An Indian independence movement'], 'en', true, 'The Meiji Restoration ended the shogunate and transformed Japan into a modern industrial state.'),
('history', 3, 'Who was the first Holy Roman Emperor?', 'Charlemagne', ARRAY['Otto I', 'Frederick Barbarossa', 'Henry IV'], 'en', true, 'Charlemagne was crowned Emperor by Pope Leo III on Christmas Day, 800 AD.'),
('history', 3, 'What was the Congress of Vienna?', 'A conference to reorganize Europe after the Napoleonic Wars', ARRAY['A meeting about trade', 'A religious council', 'A scientific congress'], 'en', true, 'The Congress of Vienna (1814-1815) restored the balance of power in Europe.'),
('history', 3, 'Who wrote "The Prince"?', 'Niccolò Machiavelli', ARRAY['Thomas More', 'Jean-Jacques Rousseau', 'John Locke'], 'en', true, 'Machiavelli wrote The Prince in 1513, a treatise on political power and statecraft.'),
('history', 3, 'What was the Battle of Thermopylae?', 'A battle where 300 Spartans fought the Persian army', ARRAY['A naval battle in Greece', 'A siege of Athens', 'A Roman conquest'], 'en', true, 'King Leonidas and 300 Spartans defended the pass at Thermopylae against Xerxes in 480 BC.'),
('history', 3, 'Who established the first Russian state?', 'The Varangians (Rurik)', ARRAY['Peter the Great', 'Ivan the Terrible', 'Vladimir the Great'], 'en', true, 'Rurik, a Varangian chieftain, established the Kievan Rus'' dynasty around 862 AD.'),
('history', 3, 'What was the significance of the Battle of Lepanto in 1571?', 'It halted Ottoman expansion in the Mediterranean', ARRAY['It ended the Crusades', 'It started the Renaissance', 'It unified Italy'], 'en', true, 'The Holy League defeated the Ottoman fleet at Lepanto on October 7, 1571.'),
('history', 3, 'Who was the Carthaginian general who crossed the Alps?', 'Hannibal Barca', ARRAY['Scipio Africanus', 'Hamilcar Barca', 'Hasdrubal'], 'en', true, 'Hannibal crossed the Alps with elephants in 218 BC to attack Rome during the Second Punic War.'),
('history', 3, 'What was the Treaty of Tordesillas?', 'An agreement dividing the New World between Spain and Portugal', ARRAY['A peace treaty ending a war', 'A trade agreement', 'A religious decree'], 'en', true, 'The Treaty of Tordesillas in 1494 divided newly discovered lands between Spain and Portugal.'),
('history', 3, 'Who founded the city of St. Petersburg?', 'Peter the Great', ARRAY['Catherine the Great', 'Ivan the Terrible', 'Alexander I'], 'en', true, 'Peter the Great founded St. Petersburg in 1703 as Russia''s new capital.'),
('history', 3, 'What was the Scramble for Africa?', 'The European colonization of Africa in the late 19th century', ARRAY['An African civil war', 'A gold rush', 'A slave trade route'], 'en', true, 'European powers divided Africa at the Berlin Conference of 1884-1885.'),
('history', 3, 'Who was Saladin?', 'A Muslim leader who recaptured Jerusalem', ARRAY['An Ottoman sultan', 'A Mongol conqueror', 'A Persian king'], 'en', true, 'Saladin defeated the Crusaders and recaptured Jerusalem in 1187.'),
('history', 3, 'What was the War of the Roses?', 'A civil war in England between York and Lancaster', ARRAY['A conflict in France', 'A religious war', 'A colonial dispute'], 'en', true, 'The Wars of the Roses (1455-1487) were fought between the houses of York and Lancaster.'),
('history', 3, 'Who was the first woman to win a Nobel Prize?', 'Marie Curie', ARRAY['Dorothy Hodgkin', 'Rosalind Franklin', 'Jane Addams'], 'en', true, 'Marie Curie won the Nobel Prize in Physics in 1903 for her work on radioactivity.'),
('history', 3, 'What event in 1773 protested British taxation in America?', 'The Boston Tea Party', ARRAY['The Boston Massacre', 'The Stamp Act Congress', 'The First Continental Congress'], 'en', true, 'Colonists dumped tea into Boston Harbor to protest taxation without representation.'),
('history', 3, 'Who was Suleiman the Magnificent?', 'The longest-reigning Ottoman sultan', ARRAY['The founder of the Ottoman Empire', 'A Persian emperor', 'A Mughal ruler'], 'en', true, 'Suleiman I ruled the Ottoman Empire from 1520 to 1566 during its golden age.'),
('history', 3, 'What was the Suez Crisis of 1956?', 'A conflict over control of the Suez Canal', ARRAY['A civil war in Egypt', 'A trade dispute', 'A natural disaster'], 'en', true, 'Britain, France, and Israel invaded Egypt over the nationalization of the Suez Canal.'),
('history', 3, 'Who was the first European to reach the Pacific Ocean overland?', 'Vasco Núñez de Balboa', ARRAY['Francisco Pizarro', 'Hernán Cortés', 'Ferdinand Magellan'], 'en', true, 'Balboa crossed the Isthmus of Panama and sighted the Pacific Ocean in 1513.'),
('history', 3, 'What was the Weimar Republic?', 'The German government between WWI and Nazi rule', ARRAY['A Roman province', 'A medieval kingdom', 'A Swiss canton'], 'en', true, 'The Weimar Republic governed Germany from 1919 to 1933 before Hitler''s rise to power.'),
('history', 3, 'Who was Hammurabi?', 'A Babylonian king who created one of the earliest law codes', ARRAY['An Egyptian pharaoh', 'A Persian emperor', 'An Assyrian general'], 'en', true, 'Hammurabi''s Code, dating to around 1750 BC, is one of the oldest written legal codes.'),
('history', 3, 'What was the Opium War?', 'A conflict between Britain and China over trade', ARRAY['A civil war in India', 'A European colonial war', 'A Japanese invasion'], 'en', true, 'The First Opium War (1839-1842) forced China to open ports and cede Hong Kong to Britain.'),
('history', 3, 'Who unified Germany in 1871?', 'Otto von Bismarck', ARRAY['Kaiser Wilhelm I', 'Frederick the Great', 'Helmut Kohl'], 'en', true, 'Bismarck, the Iron Chancellor, orchestrated German unification through wars and diplomacy.'),
('history', 3, 'What was the Dreyfus Affair?', 'A political scandal involving a wrongly accused French officer', ARRAY['A British espionage case', 'A German military trial', 'An Italian corruption scandal'], 'en', true, 'Alfred Dreyfus was wrongly convicted of treason in 1894, dividing French society for years.'),
('history', 3, 'Who led the Haitian Revolution?', 'Toussaint Louverture', ARRAY['Simon Bolivar', 'José Martí', 'Jean-Jacques Dessalines'], 'en', true, 'Toussaint Louverture led the Haitian slave revolt that began in 1791 against French colonial rule.'),
('history', 3, 'What was the significance of the Battle of Stalingrad?', 'It was the turning point of WWII on the Eastern Front', ARRAY['It ended WWI', 'It started the Cold War', 'It was the first nuclear battle'], 'en', true, 'The Soviet victory at Stalingrad (1942-1943) marked the beginning of the German retreat.'),
('history', 3, 'Who was the Minoan civilization named after?', 'King Minos', ARRAY['King Theseus', 'King Agamemnon', 'King Odysseus'], 'en', true, 'The Minoan civilization on Crete was named after the legendary King Minos by archaeologist Arthur Evans.'),
('history', 3, 'What was the Long March in China?', 'A military retreat by the Chinese Communist Party', ARRAY['A trade expedition', 'A religious pilgrimage', 'An imperial conquest'], 'en', true, 'Mao Zedong led the Communist forces on the Long March of 1934-1935 to escape Nationalist armies.'),
('history', 3, 'Who discovered the sea route around Africa to India?', 'Vasco da Gama', ARRAY['Bartolomeu Dias', 'Christopher Columbus', 'Ferdinand Magellan'], 'en', true, 'Vasco da Gama reached India in 1498 by sailing around the Cape of Good Hope.'),
('history', 3, 'What was the Domesday Book?', 'A survey of England ordered by William the Conqueror', ARRAY['A medieval Bible', 'A collection of laws', 'A history book'], 'en', true, 'The Domesday Book was completed in 1086 as a comprehensive survey of English land and resources.'),
('history', 3, 'Who was the first Mughal emperor of India?', 'Babur', ARRAY['Akbar', 'Aurangzeb', 'Shah Jahan'], 'en', true, 'Babur founded the Mughal Empire in 1526 after defeating the Sultan of Delhi at Panipat.'),
('history', 3, 'What was the significance of the Battle of Gettysburg?', 'It was the turning point of the American Civil War', ARRAY['It started the war', 'It ended the war', 'It was a Confederate victory'], 'en', true, 'The Union victory at Gettysburg in July 1863 halted Lee''s invasion of the North.'),
('history', 3, 'Who was Boudicca?', 'A Celtic queen who revolted against Roman rule', ARRAY['A Norse goddess', 'A Greek priestess', 'A medieval queen'], 'en', true, 'Boudicca led a major uprising against the Roman occupation of Britain around 60 AD.'),
('history', 3, 'What was the Spanish Inquisition?', 'A religious court established to enforce Catholic orthodoxy', ARRAY['A military campaign', 'A scientific society', 'A trade organization'], 'en', true, 'The Spanish Inquisition was established in 1478 by Ferdinand and Isabella to root out heresy.'),
('history', 3, 'Who wrote the Encyclopédie during the Enlightenment?', 'Denis Diderot and Jean d''Alembert', ARRAY['Voltaire and Rousseau', 'Montesquieu and Locke', 'Descartes and Pascal'], 'en', true, 'The Encyclopédie, published from 1751 to 1772, was a landmark work of the Enlightenment.'),
('history', 3, 'What was the Boxer Rebellion?', 'An anti-foreign uprising in China in 1900', ARRAY['A Japanese civil war', 'A Korean independence movement', 'A British colonial revolt'], 'en', true, 'Chinese nationalists known as Boxers attacked foreign nationals and Chinese Christians in 1900.'),
('history', 3, 'What was the Cuban Missile Crisis?', 'A 1962 nuclear standoff between the US and USSR', ARRAY['A Cuban civil war', 'A Caribbean trade dispute', 'A Cold War spy scandal'], 'en', true, 'The Cuban Missile Crisis brought the world to the brink of nuclear war for 13 days in October 1962.'),
('history', 3, 'Who was the first chancellor of unified Germany?', 'Otto von Bismarck', ARRAY['Kaiser Wilhelm I', 'Friedrich Ebert', 'Helmut Kohl'], 'en', true, 'Bismarck served as the first Chancellor of the German Empire from 1871 to 1890.'),
('history', 3, 'What was the Battle of Tours (Poitiers) in 732?', 'A battle that stopped the Arab advance into Europe', ARRAY['A crusade battle', 'A Viking raid', 'A Roman conquest'], 'en', true, 'Charles Martel defeated the Umayyad forces at Tours in 732, halting their advance into western Europe.'),
('history', 3, 'Who was the emperor of Ethiopia who resisted Italian colonization?', 'Menelik II', ARRAY['Haile Selassie', 'Tewodros II', 'Yohannes IV'], 'en', true, 'Emperor Menelik II defeated the Italians at the Battle of Adwa in 1896.'),
('history', 3, 'What was the Glorious Revolution?', 'The overthrow of King James II in 1688', ARRAY['The French Revolution', 'The American Revolution', 'The English Civil War'], 'en', true, 'The Glorious Revolution established constitutional monarchy and parliamentary sovereignty in England.'),
('history', 3, 'Who was the first European to reach Brazil?', 'Pedro Álvares Cabral', ARRAY['Vasco da Gama', 'Christopher Columbus', 'Amerigo Vespucci'], 'en', true, 'Portuguese explorer Cabral reached Brazil in 1500 while sailing to India.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 4, 'What was the Diet of Worms?', 'An assembly where Martin Luther defended his writings', ARRAY['A medieval feast', 'A Roman court', 'A scientific conference'], 'en', true, 'Martin Luther appeared before the Diet of Worms in 1521 and refused to recant his writings.'),
('history', 4, 'Who was the Sassanid Empire named after?', 'Sasan, ancestor of the dynasty', ARRAY['A Persian god', 'A city', 'A military leader'], 'en', true, 'The Sassanid Empire (224-651 AD) was the last major Persian empire before the Arab conquest.'),
('history', 4, 'What was the Defenestration of Prague?', 'An event where officials were thrown from a window, triggering the Thirty Years'' War', ARRAY['A plague outbreak', 'A royal coronation', 'A trade agreement'], 'en', true, 'In 1618, Protestant nobles threw Catholic officials from a window, sparking the Thirty Years'' War.'),
('history', 4, 'Who was Akbar the Great?', 'A Mughal emperor known for religious tolerance', ARRAY['An Ottoman sultan', 'A Persian shah', 'A Mongol conqueror'], 'en', true, 'Akbar ruled the Mughal Empire from 1556 to 1605 and promoted tolerance across religions.'),
('history', 4, 'What was the significance of the Battle of Cannae?', 'Hannibal''s greatest tactical victory over Rome', ARRAY['The fall of Carthage', 'The founding of Rome', 'A naval battle'], 'en', true, 'Hannibal''s double envelopment at Cannae in 216 BC destroyed a much larger Roman army.'),
('history', 4, 'Who was the first European to see the Pacific Ocean?', 'Vasco Núñez de Balboa', ARRAY['Ferdinand Magellan', 'Francis Drake', 'James Cook'], 'en', true, 'Balboa crossed the Isthmus of Panama and reached the Pacific in 1513.'),
('history', 4, 'What was the Concordat of Worms?', 'An agreement settling the Investiture Controversy', ARRAY['A trade treaty', 'A peace accord', 'A religious crusade'], 'en', true, 'The Concordat of Worms in 1122 resolved the conflict over the appointment of church officials.'),
('history', 4, 'Who was Ashoka the Great?', 'An Indian emperor who promoted Buddhism', ARRAY['A Chinese philosopher', 'A Persian king', 'A Japanese shogun'], 'en', true, 'Ashoka of the Maurya Dynasty converted to Buddhism and spread it throughout his empire around 260 BC.'),
('history', 4, 'What was the Battle of Manzikert?', 'A Seljuk Turkish victory that opened Anatolia to Turkish settlement', ARRAY['A Crusader battle', 'A Mongol invasion', 'An Arab conquest'], 'en', true, 'The Seljuk victory at Manzikert in 1071 led to the Turkish colonization of Anatolia.'),
('history', 4, 'Who established the Carolingian dynasty?', 'Pepin the Short', ARRAY['Charlemagne', 'Charles Martel', 'Clovis I'], 'en', true, 'Pepin the Short deposed the last Merovingian king and founded the Carolingian dynasty in 751.'),
('history', 4, 'What was the Taiping Rebellion?', 'A massive civil war in China led by Hong Xiuquan', ARRAY['A Japanese uprising', 'A Korean revolt', 'An Indian mutiny'], 'en', true, 'The Taiping Rebellion (1850-1864) killed an estimated 20-30 million people in China.'),
('history', 4, 'Who was Cyrus the Great?', 'The founder of the Persian Achaemenid Empire', ARRAY['The last Babylonian king', 'An Egyptian pharaoh', 'A Median general'], 'en', true, 'Cyrus the Great founded the Achaemenid Empire around 550 BC and freed the Jews from Babylon.'),
('history', 4, 'What was the significance of the Edict of Milan?', 'It legalized Christianity in the Roman Empire', ARRAY['It divided the empire', 'It outlawed paganism', 'It ended the Republic'], 'en', true, 'Constantine and Licinius issued the Edict of Milan in 313, granting religious freedom.'),
('history', 4, 'Who was Mansa Musa?', 'The richest ruler of the Mali Empire', ARRAY['An Ethiopian emperor', 'A Songhai king', 'A Ghanaian chief'], 'en', true, 'Mansa Musa''s pilgrimage to Mecca in 1324 displayed such wealth that it devalued gold in Egypt.'),
('history', 4, 'What was the War of Spanish Succession?', 'A conflict over who would inherit the Spanish throne', ARRAY['A colonial war', 'A religious conflict', 'A trade dispute'], 'en', true, 'The War of Spanish Succession (1701-1714) ended with the Treaty of Utrecht.'),
('history', 4, 'Who was Zheng He?', 'A Chinese admiral who led massive maritime expeditions', ARRAY['A Japanese samurai', 'A Mongol general', 'A Korean king'], 'en', true, 'Zheng He commanded treasure fleets across the Indian Ocean from 1405 to 1433.'),
('history', 4, 'What was the Gunpowder Plot?', 'A 1605 conspiracy to blow up the English Parliament', ARRAY['A Chinese invention', 'A military strategy', 'A naval battle'], 'en', true, 'Guy Fawkes was caught guarding explosives beneath Parliament on November 5, 1605.'),
('history', 4, 'Who founded the Jesuit order?', 'Ignatius of Loyola', ARRAY['Martin Luther', 'Francis of Assisi', 'Thomas Aquinas'], 'en', true, 'Ignatius of Loyola founded the Society of Jesus (Jesuits) in 1540 during the Counter-Reformation.'),
('history', 4, 'What was the Battle of Agincourt?', 'An English victory over France during the Hundred Years'' War', ARRAY['A Crusader battle', 'A Roman conquest', 'A Viking raid'], 'en', true, 'Henry V''s English longbowmen defeated a much larger French army at Agincourt in 1415.'),
('history', 4, 'Who was the first female pharaoh of Egypt?', 'Hatshepsut', ARRAY['Cleopatra', 'Nefertiti', 'Sobekneferu'], 'en', true, 'Hatshepsut ruled Egypt as pharaoh from approximately 1478 to 1458 BC during the 18th Dynasty.'),
('history', 4, 'What was the significance of the Council of Trent?', 'It defined Catholic doctrine during the Counter-Reformation', ARRAY['It started the Crusades', 'It split the Eastern and Western churches', 'It founded the papacy'], 'en', true, 'The Council of Trent (1545-1563) reformed the Catholic Church in response to Protestantism.'),
('history', 4, 'Who was Tokugawa Ieyasu?', 'The founder of the Tokugawa Shogunate in Japan', ARRAY['The last samurai', 'A Buddhist monk', 'A Chinese emperor'], 'en', true, 'Tokugawa Ieyasu established the Tokugawa Shogunate in 1603, unifying Japan for 250 years.'),
('history', 4, 'What was the Sepoy Mutiny?', 'An Indian rebellion against the British East India Company in 1857', ARRAY['A Chinese revolt', 'A Japanese uprising', 'An African rebellion'], 'en', true, 'The Indian Rebellion of 1857 led to the dissolution of the East India Company and direct British rule.'),
('history', 4, 'Who was Sargon of Akkad?', 'The founder of the first known empire in history', ARRAY['An Egyptian pharaoh', 'A Persian king', 'A Roman consul'], 'en', true, 'Sargon of Akkad created the Akkadian Empire around 2334 BC in Mesopotamia.'),
('history', 4, 'What was the Peace of Augsburg?', 'A treaty allowing German princes to choose Catholicism or Lutheranism', ARRAY['A trade agreement', 'A military alliance', 'A colonial pact'], 'en', true, 'The Peace of Augsburg in 1555 established the principle of cuius regio, eius religio.'),
('history', 4, 'Who was Sundiata Keita?', 'The founder of the Mali Empire', ARRAY['A Songhai emperor', 'A Ghanaian king', 'An Ethiopian ruler'], 'en', true, 'Sundiata Keita founded the Mali Empire around 1235 after the Battle of Kirina.'),
('history', 4, 'What was the Zimmermann Telegram?', 'A secret German message proposing a Mexican alliance against the US', ARRAY['A peace proposal', 'A trade agreement', 'A spy communication'], 'en', true, 'The intercepted Zimmermann Telegram in 1917 helped push the US into World War I.'),
('history', 4, 'Who was Tamerlane?', 'A Turco-Mongol conqueror who built a vast empire', ARRAY['An Ottoman sultan', 'A Mughal emperor', 'A Persian shah'], 'en', true, 'Tamerlane (Timur) conquered much of Central Asia and the Middle East in the 14th century.'),
('history', 4, 'What was the Hanseatic League?', 'A medieval commercial alliance of northern European trading cities', ARRAY['A military alliance', 'A religious order', 'A royal dynasty'], 'en', true, 'The Hanseatic League dominated Baltic and North Sea trade from the 13th to 17th centuries.'),
('history', 4, 'Who was Nefertiti?', 'An ancient Egyptian queen famous for her beauty', ARRAY['A Greek goddess', 'A Roman empress', 'A Persian princess'], 'en', true, 'Nefertiti was the wife of Pharaoh Akhenaten and is known for her iconic painted bust.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('history', 5, 'What was the name of Charlemagne''s legendary sword?', 'Joyeuse', ARRAY['Durandal', 'Excalibur', 'Hrunting'], 'en', true, 'Joyeuse is the legendary sword of Charlemagne, mentioned in the Song of Roland.'),
('history', 5, 'In what year was the Edict of Nantes revoked?', '1685', ARRAY['1672', '1598', '1690'], 'en', true, 'Louis XIV revoked the Edict of Nantes with the Edict of Fontainebleau in 1685.'),
('history', 5, 'What was the Pragmatic Sanction of 1713?', 'A decree ensuring female succession to the Habsburg throne', ARRAY['A trade agreement', 'A religious edict', 'A military alliance'], 'en', true, 'Charles VI issued the Pragmatic Sanction to allow his daughter Maria Theresa to inherit.'),
('history', 5, 'Who was the last Abbasid Caliph of Baghdad?', 'Al-Musta''sim', ARRAY['Al-Mutasim', 'Al-Mamun', 'Harun al-Rashid'], 'en', true, 'Al-Musta''sim was killed when the Mongols sacked Baghdad in 1258.'),
('history', 5, 'What was the Delian League?', 'An alliance of Greek city-states led by Athens', ARRAY['A Roman federation', 'A Persian alliance', 'A Spartan pact'], 'en', true, 'The Delian League was formed in 478 BC to defend against Persia but became an Athenian empire.'),
('history', 5, 'Who was the first Viking to reach North America?', 'Leif Erikson', ARRAY['Erik the Red', 'Ragnar Lothbrok', 'Harald Hardrada'], 'en', true, 'Leif Erikson reached Vinland (likely Newfoundland) around 1000 AD, centuries before Columbus.'),
('history', 5, 'What was the Code of Ur-Nammu?', 'The oldest surviving legal code in history', ARRAY['An Egyptian religious text', 'A Chinese philosophy', 'A Greek constitution'], 'en', true, 'The Code of Ur-Nammu dates to around 2100 BC in Sumer, predating Hammurabi''s Code.'),
('history', 5, 'Who was Empress Wu Zetian?', 'The only woman to rule China as emperor in her own right', ARRAY['A Japanese empress', 'A Korean queen', 'A Vietnamese ruler'], 'en', true, 'Wu Zetian ruled China from 690 to 705 AD during the Tang and Zhou dynasties.'),
('history', 5, 'What was the significance of the Battle of Zama?', 'It ended the Second Punic War with a Roman victory', ARRAY['It began the Roman Republic', 'It destroyed Carthage', 'It conquered Greece'], 'en', true, 'Scipio Africanus defeated Hannibal at Zama in 202 BC, ending Carthage''s military power.'),
('history', 5, 'Who established the Fatimid Caliphate?', 'Abdullah al-Mahdi Billah', ARRAY['Saladin', 'Al-Mansur', 'Harun al-Rashid'], 'en', true, 'The Fatimid Caliphate was established in 909 AD in North Africa as a Shia Muslim dynasty.'),
('history', 5, 'What was the Albigensian Crusade?', 'A crusade against the Cathars in southern France', ARRAY['A crusade to Jerusalem', 'A war against the Moors', 'A conflict with the Ottomans'], 'en', true, 'The Albigensian Crusade (1209-1229) was launched against Cathar heretics in Languedoc.'),
('history', 5, 'Who was Pachacuti?', 'The Inca ruler who transformed Cusco into an empire', ARRAY['An Aztec emperor', 'A Maya king', 'An Olmec priest'], 'en', true, 'Pachacuti expanded the Inca Empire dramatically in the 15th century from his base in Cusco.'),
('history', 5, 'What was the Investiture Controversy?', 'A conflict between the papacy and Holy Roman Empire over appointing bishops', ARRAY['A trade dispute', 'A colonial conflict', 'A succession crisis'], 'en', true, 'The Investiture Controversy (1076-1122) pitted popes against emperors over clerical appointments.'),
('history', 5, 'Who was the oldest parliament in the world established by?', 'The Icelanders (Althing)', ARRAY['The English', 'The Greeks', 'The Romans'], 'en', true, 'The Althing was founded in 930 AD at Thingvellir, making it the world''s oldest parliament.'),
('history', 5, 'What was the significance of the Battle of Adrianople in 378 AD?', 'The Goths destroyed a Roman army, signaling Rome''s vulnerability', ARRAY['It founded Constantinople', 'It ended the Republic', 'It split the empire'], 'en', true, 'Emperor Valens was killed at Adrianople, demonstrating that barbarian forces could defeat Rome.'),
('history', 5, 'Who was Ibn Battuta?', 'A Moroccan explorer who traveled across the medieval Islamic world', ARRAY['An Arab mathematician', 'A Persian poet', 'An Ottoman admiral'], 'en', true, 'Ibn Battuta traveled over 120,000 km across the Islamic world from 1325 to 1354.'),
('history', 5, 'What was the Fourth Crusade known for?', 'The sack of Constantinople instead of reaching the Holy Land', ARRAY['The capture of Jerusalem', 'The founding of Crusader states', 'The defeat of Saladin'], 'en', true, 'The Fourth Crusade in 1204 infamously diverted to sack the Christian city of Constantinople.'),
('history', 5, 'Who was Tiglath-Pileser III?', 'An Assyrian king who created the Neo-Assyrian Empire', ARRAY['A Babylonian ruler', 'A Persian emperor', 'A Hittite king'], 'en', true, 'Tiglath-Pileser III reformed the Assyrian military and administration around 745-727 BC.'),
('history', 5, 'What was the Great Schism of 1054?', 'The split between the Roman Catholic and Eastern Orthodox churches', ARRAY['The Protestant Reformation', 'The Avignon Papacy', 'The Council of Nicaea'], 'en', true, 'The Great Schism permanently divided Christianity into Catholic and Orthodox branches.'),
('history', 5, 'Who was Prester John?', 'A legendary Christian king believed to rule in Africa or Asia', ARRAY['A real medieval pope', 'A famous crusader', 'A Byzantine emperor'], 'en', true, 'The myth of Prester John motivated European exploration from the 12th to 17th centuries.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 1, 'Quel est le plus petit continent du monde ?', 'L''Océanie', ARRAY['L''Europe', 'L''Antarctique', 'L''Amérique du Sud'], 'fr', true, 'L''Océanie (ou Australie comme continent) est le plus petit des continents.'),
('geography', 1, 'Dans quel pays se trouve la tour penchée de Pise ?', 'L''Italie', ARRAY['La France', 'L''Espagne', 'La Grèce'], 'fr', true, 'La tour de Pise se trouve en Toscane, en Italie, et penche depuis sa construction au XIIe siècle.'),
('geography', 1, 'Quelle est la capitale du Mexique ?', 'Mexico', ARRAY['Cancún', 'Guadalajara', 'Monterrey'], 'fr', true, 'Mexico est la capitale et la plus grande ville du Mexique, avec plus de 21 millions d''habitants.'),
('geography', 1, 'Quel océan se trouve entre l''Europe et l''Amérique ?', 'L''océan Atlantique', ARRAY['L''océan Pacifique', 'L''océan Indien', 'L''océan Arctique'], 'fr', true, 'L''océan Atlantique sépare les continents européen et américain.'),
('geography', 1, 'Dans quel pays se trouve le mont Kilimandjaro ?', 'La Tanzanie', ARRAY['Le Kenya', 'L''Éthiopie', 'L''Ouganda'], 'fr', true, 'Le Kilimandjaro, plus haut sommet d''Afrique à 5 895 m, se trouve en Tanzanie.'),
('geography', 1, 'Quelle est la capitale de la Russie ?', 'Moscou', ARRAY['Saint-Pétersbourg', 'Kiev', 'Varsovie'], 'fr', true, 'Moscou est la capitale de la Russie et sa plus grande ville.'),
('geography', 1, 'Quel pays est surnommé le pays des tulipes ?', 'Les Pays-Bas', ARRAY['La Belgique', 'Le Danemark', 'La Suède'], 'fr', true, 'Les Pays-Bas sont célèbres pour leurs champs de tulipes et le marché aux fleurs d''Amsterdam.'),
('geography', 1, 'Sur quel continent se trouve l''Inde ?', 'L''Asie', ARRAY['L''Afrique', 'L''Europe', 'L''Océanie'], 'fr', true, 'L''Inde est un grand pays du sud de l''Asie, bordé par l''océan Indien.'),
('geography', 1, 'Quelle est la capitale du Portugal ?', 'Lisbonne', ARRAY['Porto', 'Faro', 'Coimbra'], 'fr', true, 'Lisbonne est la capitale du Portugal, située sur les rives du Tage.'),
('geography', 1, 'Quel fleuve traverse l''Égypte ?', 'Le Nil', ARRAY['Le Congo', 'Le Niger', 'Le Zambèze'], 'fr', true, 'Le Nil traverse l''Égypte du sud au nord et se jette dans la mer Méditerranée.'),
('geography', 1, 'Quel pays a pour forme un hexagone ?', 'La France', ARRAY['L''Espagne', 'L''Allemagne', 'La Pologne'], 'fr', true, 'La France est souvent surnommée l''Hexagone en raison de sa forme géométrique.'),
('geography', 1, 'Quelle est la monnaie utilisée au Japon ?', 'Le yen', ARRAY['Le yuan', 'Le won', 'Le dollar'], 'fr', true, 'Le yen est la monnaie officielle du Japon depuis 1871.'),
('geography', 1, 'Quel pays est le plus peuplé d''Afrique ?', 'Le Nigeria', ARRAY['L''Éthiopie', 'L''Égypte', 'L''Afrique du Sud'], 'fr', true, 'Le Nigeria est le pays le plus peuplé d''Afrique avec plus de 220 millions d''habitants.'),
('geography', 1, 'Quelle est la capitale de la Turquie ?', 'Ankara', ARRAY['Istanbul', 'Izmir', 'Antalya'], 'fr', true, 'Ankara est la capitale de la Turquie depuis 1923, bien qu''Istanbul soit plus grande.'),
('geography', 1, 'Quel est le plus grand désert froid du monde ?', 'L''Antarctique', ARRAY['Le Sahara', 'Le Gobi', 'L''Arctique'], 'fr', true, 'L''Antarctique est techniquement le plus grand désert du monde car il reçoit très peu de précipitations.'),
('geography', 1, 'Dans quel pays se trouvent les chutes du Niagara ?', 'Le Canada et les États-Unis', ARRAY['Le Brésil', 'L''Argentine', 'Le Mexique'], 'fr', true, 'Les chutes du Niagara se trouvent à la frontière entre l''Ontario (Canada) et New York (États-Unis).'),
