('geography', 3, 'Quel est le fleuve le plus long d''Afrique ?', 'Le Nil', ARRAY['Le Congo', 'Le Niger', 'Le Zambèze'], 'fr', true, 'Le Nil mesure environ 6 650 km, traversant 11 pays d''Afrique du sud au nord.'),
('geography', 3, 'Quelle est la capitale du Pakistan ?', 'Islamabad', ARRAY['Karachi', 'Lahore', 'Rawalpindi'], 'fr', true, 'Islamabad est la capitale du Pakistan depuis 1967, construite pour remplacer Karachi.'),
('geography', 3, 'Quel pays possède le plus de frontières terrestres ?', 'La Chine et la Russie', ARRAY['Le Brésil', 'L''Allemagne', 'La France'], 'fr', true, 'La Chine et la Russie partagent chacune des frontières avec 14 pays.'),
('geography', 3, 'Quelle est la plus grande île de l''océan Indien ?', 'Madagascar', ARRAY['Le Sri Lanka', 'Sumatra', 'Bornéo'], 'fr', true, 'Madagascar est la quatrième plus grande île du monde avec 587 041 km².'),
('geography', 3, 'Quel pays produit le plus de café au monde ?', 'Le Brésil', ARRAY['La Colombie', 'Le Vietnam', 'L''Éthiopie'], 'fr', true, 'Le Brésil est le premier producteur mondial de café, représentant environ un tiers de la production.'),
('geography', 3, 'Quelle est la capitale de la Nouvelle-Zélande ?', 'Wellington', ARRAY['Auckland', 'Christchurch', 'Queenstown'], 'fr', true, 'Wellington est la capitale de la Nouvelle-Zélande, bien qu''Auckland soit plus peuplée.'),
('geography', 3, 'Quel désert se trouve en Mongolie et en Chine ?', 'Le désert de Gobi', ARRAY['Le Sahara', 'Le Taklamakan', 'Le Karakoum'], 'fr', true, 'Le désert de Gobi couvre environ 1,3 million de km² entre la Mongolie et la Chine.'),
('geography', 3, 'Quel est le plus petit océan du monde ?', 'L''océan Arctique', ARRAY['L''océan Indien', 'L''océan Atlantique', 'L''océan Austral'], 'fr', true, 'L''océan Arctique, avec 14,06 millions de km², est le plus petit des cinq océans.'),
('geography', 3, 'Quelle est la capitale de la Tanzanie ?', 'Dodoma', ARRAY['Dar es Salaam', 'Arusha', 'Zanzibar'], 'fr', true, 'Dodoma est la capitale officielle de la Tanzanie depuis 1974, bien que Dar es Salaam reste la plus grande ville.'),
('geography', 3, 'Quel pays d''Asie a la plus grande superficie ?', 'La Russie', ARRAY['La Chine', 'L''Inde', 'Le Kazakhstan'], 'fr', true, 'La partie asiatique de la Russie couvre environ 13 millions de km².'),
('geography', 3, 'Quelle rivière forme une grande partie de la frontière entre les États-Unis et le Mexique ?', 'Le Rio Grande', ARRAY['Le Colorado', 'Le Mississippi', 'Le Missouri'], 'fr', true, 'Le Rio Grande (Río Bravo en espagnol) forme la frontière sur environ 2 000 km.'),
('geography', 3, 'Quel pays européen est une péninsule entourée par la mer Baltique et la mer du Nord ?', 'Le Danemark', ARRAY['La Suède', 'La Finlande', 'La Norvège'], 'fr', true, 'La péninsule du Jutland, qui forme le Danemark continental, sépare la mer du Nord de la Baltique.'),
('geography', 3, 'Quelle est la plus grande ville d''Amérique du Sud ?', 'São Paulo', ARRAY['Buenos Aires', 'Rio de Janeiro', 'Bogota'], 'fr', true, 'São Paulo, au Brésil, compte environ 22 millions d''habitants dans son agglomération.'),
('geography', 3, 'Quel volcan est le plus haut d''Europe ?', 'L''Etna', ARRAY['Le Vésuve', 'Le Stromboli', 'L''Hekla'], 'fr', true, 'L''Etna, en Sicile, culmine à environ 3 357 m et est le plus haut volcan actif d''Europe.'),
('geography', 3, 'Quelle est la capitale du Sri Lanka ?', 'Sri Jayewardenepura Kotte', ARRAY['Colombo', 'Kandy', 'Galle'], 'fr', true, 'Sri Jayewardenepura Kotte est la capitale législative, tandis que Colombo est la capitale commerciale.'),
('geography', 3, 'Quel plateau est surnommé le toit du monde ?', 'Le plateau du Tibet', ARRAY['Le plateau éthiopien', 'Le plateau iranien', 'L''Altiplano'], 'fr', true, 'Le plateau du Tibet, à plus de 4 500 m d''altitude moyenne, est le plus haut plateau du monde.'),
('geography', 3, 'Quel pays possède la plus grande forêt boréale ?', 'La Russie', ARRAY['Le Canada', 'La Finlande', 'La Suède'], 'fr', true, 'La taïga russe est la plus grande forêt boréale du monde, couvrant des millions de km².'),
('geography', 3, 'Quelle est la capitale de l''Azerbaïdjan ?', 'Bakou', ARRAY['Tbilissi', 'Erevan', 'Achgabat'], 'fr', true, 'Bakou est la capitale de l''Azerbaïdjan, située au bord de la mer Caspienne.'),
('geography', 3, 'Quel est le plus grand pays insulaire du monde ?', 'L''Indonésie', ARRAY['Madagascar', 'Le Japon', 'Les Philippines'], 'fr', true, 'L''Indonésie, avec ses 17 000 îles, est le plus grand pays insulaire avec 1,9 million de km².'),
('geography', 3, 'Quel canal relie la mer Méditerranée à la mer Rouge ?', 'Le canal de Suez', ARRAY['Le canal de Panama', 'Le canal de Corinthe', 'Le canal de Kiel'], 'fr', true, 'Le canal de Suez, en Égypte, mesure 193 km et a été ouvert en 1869.'),
('geography', 3, 'Quel pays africain est entièrement entouré par l''Afrique du Sud ?', 'Le Lesotho', ARRAY['L''Eswatini', 'Le Malawi', 'Le Botswana'], 'fr', true, 'Le Lesotho est complètement enclavé dans l''Afrique du Sud, un cas unique en Afrique.'),
('geography', 3, 'Quelle est la capitale administrative de la Bolivie ?', 'Sucre', ARRAY['La Paz', 'Cochabamba', 'Santa Cruz'], 'fr', true, 'Sucre est la capitale constitutionnelle de la Bolivie, tandis que La Paz est le siège du gouvernement.'),
('geography', 3, 'Quel est le fleuve le plus large du monde ?', 'Le Rio de la Plata', ARRAY['L''Amazone', 'Le Congo', 'Le Mississippi'], 'fr', true, 'L''estuaire du Rio de la Plata entre l''Argentine et l''Uruguay mesure jusqu''à 220 km de large.'),
('geography', 3, 'Quelle mer intérieure rétrécit dangereusement en Asie centrale ?', 'La mer d''Aral', ARRAY['La mer Caspienne', 'Le lac Baïkal', 'Le lac Balkhach'], 'fr', true, 'La mer d''Aral a perdu 90 % de sa surface depuis les années 1960 à cause de l''irrigation.'),
('geography', 3, 'Quel pays possède le plus de patrimoine mondial UNESCO ?', 'L''Italie', ARRAY['La Chine', 'La France', 'L''Espagne'], 'fr', true, 'L''Italie détient le record avec 58 sites classés au patrimoine mondial de l''UNESCO.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 4, 'Quel est le lac le plus profond du monde ?', 'Le lac Baïkal', ARRAY['Le lac Tanganyika', 'Le lac Supérieur', 'Le lac Malawi'], 'fr', true, 'Le lac Baïkal en Sibérie atteint 1 642 m de profondeur et contient 20 % de l''eau douce mondiale.'),
('geography', 4, 'Quel est le seul pays traversé à la fois par l''équateur et le tropique du Capricorne ?', 'Le Brésil', ARRAY['La Colombie', 'L''Indonésie', 'Le Congo'], 'fr', true, 'Le Brésil est traversé par l''équateur au nord et le tropique du Capricorne au sud.'),
('geography', 4, 'Quelle est la plus haute capitale d''Amérique du Sud ?', 'Quito', ARRAY['Bogota', 'La Paz', 'Sucre'], 'fr', true, 'Quito, capitale de l''Équateur, se situe à 2 850 m d''altitude (La Paz est siège du gouvernement mais pas capitale officielle).'),
('geography', 4, 'Quel pays possède l''île de Socotra ?', 'Le Yémen', ARRAY['Oman', 'L''Arabie saoudite', 'Djibouti'], 'fr', true, 'L''île de Socotra, classée UNESCO, appartient au Yémen et possède une biodiversité unique.'),
('geography', 4, 'Quel est le plus long récif corallien de l''hémisphère nord ?', 'La barrière de corail du Belize', ARRAY['La barrière de corail de Floride', 'Le récif de la mer Rouge', 'Le récif d''Okinawa'], 'fr', true, 'La barrière de corail du Belize mesure environ 300 km, classée au patrimoine mondial.'),
('geography', 4, 'Quel pays d''Asie centrale est doublement enclavé ?', 'Le Liechtenstein et l''Ouzbékistan', ARRAY['Le Kazakhstan', 'Le Kirghizistan', 'Le Tadjikistan'], 'fr', true, 'L''Ouzbékistan est doublement enclavé : entouré de pays eux-mêmes sans accès à la mer.'),
('geography', 4, 'Quel est le plus haut volcan du monde ?', 'L''Ojos del Salado', ARRAY['Le Cotopaxi', 'Le Kilimandjaro', 'Le mont Rainier'], 'fr', true, 'L''Ojos del Salado, à la frontière Argentine-Chili, culmine à 6 893 m.'),
('geography', 4, 'Quelle est la ville la plus septentrionale de plus de 100 000 habitants ?', 'Mourmansk', ARRAY['Tromsø', 'Reykjavik', 'Norilsk'], 'fr', true, 'Mourmansk, en Russie, est la plus grande ville au-dessus du cercle polaire arctique.'),
('geography', 4, 'Quel fleuve africain forme les chutes Victoria ?', 'Le Zambèze', ARRAY['Le Congo', 'Le Niger', 'Le Nil'], 'fr', true, 'Les chutes Victoria, sur le Zambèze, mesurent 1 708 m de large et 108 m de haut.'),
('geography', 4, 'Quel pays possède le plus grand nombre de langues officielles ?', 'L''Afrique du Sud', ARRAY['L''Inde', 'La Suisse', 'Le Canada'], 'fr', true, 'L''Afrique du Sud reconnaît 11 langues officielles dans sa constitution.'),
('geography', 4, 'Quel est le point le plus éloigné de tout océan sur Terre ?', 'Le pôle d''inaccessibilité eurasien', ARRAY['Le centre du Sahara', 'Le Tibet', 'Le centre de l''Australie'], 'fr', true, 'Le pôle continental d''inaccessibilité se trouve au nord-ouest de la Chine, à 2 510 km de tout océan.'),
('geography', 4, 'Quelle est la plus grande île volcanique du monde ?', 'L''Islande', ARRAY['Hawaï', 'La Réunion', 'Java'], 'fr', true, 'L''Islande, avec 103 000 km², est la plus grande île volcanique du monde.'),
('geography', 4, 'Quel pays abrite la plus grande partie de la mer d''Aral ?', 'L''Ouzbékistan et le Kazakhstan', ARRAY['Le Turkménistan', 'Le Kirghizistan', 'Le Tadjikistan'], 'fr', true, 'La mer d''Aral est partagée entre l''Ouzbékistan et le Kazakhstan.'),
('geography', 4, 'Quelle est la capitale de Nauru ?', 'Yaren', ARRAY['Suva', 'Tarawa', 'Funafuti'], 'fr', true, 'Yaren est le district principal de Nauru, le plus petit pays insulaire du Pacifique.'),
('geography', 4, 'Quel est le fleuve le plus long du monde sans barrage ?', 'L''Amazone', ARRAY['Le Nil', 'Le Mississippi', 'Le Congo'], 'fr', true, 'Le cours principal de l''Amazone n''a aucun barrage sur sa longueur.'),
('geography', 4, 'Quelle péninsule partage la Norvège, la Suède et une partie de la Finlande ?', 'La péninsule scandinave', ARRAY['La péninsule ibérique', 'La péninsule balkanique', 'La péninsule de Kola'], 'fr', true, 'La péninsule scandinave s''étend sur environ 1 850 km en Europe du Nord.'),
('geography', 4, 'Quel est le pays le plus long du monde en proportion ?', 'Le Chili', ARRAY['La Norvège', 'Le Vietnam', 'L''Italie'], 'fr', true, 'Le Chili s''étend sur 4 300 km du nord au sud mais ne fait que 177 km de large en moyenne.'),
('geography', 4, 'Quelle est la plus grande caldera du monde ?', 'La caldera de Toba', ARRAY['La caldera de Yellowstone', 'La caldera de Santorin', 'La caldera du Ngorongoro'], 'fr', true, 'La caldera de Toba à Sumatra mesure 100 km de long, formée il y a 74 000 ans.'),
('geography', 4, 'Quel pays possède le plus grand glacier hors des pôles ?', 'Le Pakistan', ARRAY['La Norvège', 'Le Chili', 'L''Islande'], 'fr', true, 'Le glacier de Siachen au Pakistan, dans le Karakoram, mesure 76 km de long.'),
('geography', 4, 'Quelle est la température la plus élevée jamais enregistrée sur Terre ?', '56,7°C dans la Vallée de la Mort', ARRAY['54°C au Sahara', '58°C en Libye', '55°C en Arabie'], 'fr', true, 'La température record de 56,7°C a été mesurée à Furnace Creek, Californie, le 10 juillet 1913.'),
('geography', 4, 'Quel est le seul pays au monde dont le drapeau n''est pas rectangulaire ?', 'Le Népal', ARRAY['La Suisse', 'Le Vatican', 'Le Bhoutan'], 'fr', true, 'Le drapeau du Népal est composé de deux triangles superposés.'),
('geography', 4, 'Quel est le plus grand delta du monde ?', 'Le delta du Gange-Brahmapoutre', ARRAY['Le delta du Mékong', 'Le delta du Mississippi', 'Le delta du Nil'], 'fr', true, 'Le delta du Gange-Brahmapoutre au Bangladesh couvre environ 105 000 km².'),
('geography', 4, 'Quel pays européen possède le plus de parcs nationaux ?', 'La Norvège', ARRAY['La France', 'L''Italie', 'L''Espagne'], 'fr', true, 'La Norvège possède 47 parcs nationaux, le plus grand nombre en Europe.'),
('geography', 4, 'Quelle est la mer la plus grande du monde ?', 'La mer de Chine méridionale', ARRAY['La mer Méditerranée', 'La mer des Caraïbes', 'La mer d''Arabie'], 'fr', true, 'La mer de Chine méridionale couvre environ 3,5 millions de km².'),
('geography', 4, 'Quel pays possède le plus de lacs de cratère ?', 'L''Ouganda', ARRAY['L''Islande', 'Le Cameroun', 'Les Philippines'], 'fr', true, 'L''Ouganda possède un nombre remarquable de lacs de cratère dans la région de Fort Portal.'),
('geography', 4, 'Quel est le pays le plus boisé d''Europe en pourcentage ?', 'La Finlande', ARRAY['La Suède', 'La Norvège', 'La Russie'], 'fr', true, 'Environ 73 % du territoire finlandais est couvert de forêts.'),
('geography', 4, 'Quelle ville détient le record de la plus grande altitude parmi les capitales de pays ?', 'La Paz (siège du gouvernement)', ARRAY['Quito', 'Bogota', 'Addis-Abeba'], 'fr', true, 'La Paz se situe à 3 640 m d''altitude, bien qu''elle soit le siège du gouvernement et non la capitale constitutionnelle.'),
('geography', 4, 'Quel pays possède la plus grande zone économique exclusive maritime ?', 'La France', ARRAY['Les États-Unis', 'L''Australie', 'Le Royaume-Uni'], 'fr', true, 'La France possède la plus grande ZEE du monde grâce à ses territoires d''outre-mer.'),
('geography', 4, 'Quelle rivière souterraine est la plus longue du monde ?', 'La rivière souterraine de Puerto Princesa', ARRAY['La rivière souterraine de Postojna', 'La Timavo', 'La rivière de Waitomo'], 'fr', true, 'La rivière souterraine de Puerto Princesa aux Philippines mesure 8,2 km navigables.'),
('geography', 4, 'Quel est le plus haut sommet d''Océanie ?', 'Le Puncak Jaya', ARRAY['Le mont Cook', 'Le mont Wilhelm', 'Le Mauna Kea'], 'fr', true, 'Le Puncak Jaya (ou Pyramide Carstensz) en Papouasie culmine à 4 884 m.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 5, 'Quel est le plus grand atoll du monde par superficie de lagon ?', 'L''atoll de Kwajalein', ARRAY['L''atoll de Rangiroa', 'L''atoll d''Aldabra', 'L''atoll de Bikini'], 'fr', true, 'L''atoll de Kwajalein dans les îles Marshall possède le plus grand lagon du monde (2 174 km²).'),
('geography', 5, 'Quel est le point triple tectonique le plus connu ?', 'La jonction d''Afar', ARRAY['Le point triple de Rodrigues', 'Le point triple du Chili', 'Le point triple des Galápagos'], 'fr', true, 'La jonction d''Afar en Éthiopie est le point de rencontre de trois plaques tectoniques.'),
('geography', 5, 'Quel pays possède l''île Bouvet, l''île la plus isolée du monde ?', 'La Norvège', ARRAY['Le Royaume-Uni', 'La France', 'l''Afrique du Sud'], 'fr', true, 'L''île Bouvet, territoire norvégien, est à 1 639 km de la terre la plus proche.'),
('geography', 5, 'Quel est le plus long système de grottes au monde ?', 'Mammoth Cave', ARRAY['La grotte de Postojna', 'La grotte de Son Doong', 'La grotte de Lechuguilla'], 'fr', true, 'Mammoth Cave dans le Kentucky possède plus de 670 km de passages explorés.'),
('geography', 5, 'Quelle est la seule mer sans côtes ?', 'La mer des Sargasses', ARRAY['La mer Caspienne', 'La mer d''Aral', 'La mer Morte'], 'fr', true, 'La mer des Sargasses dans l''Atlantique est délimitée uniquement par des courants océaniques.'),
('geography', 5, 'Quel est le plus haut lac navigable du monde ?', 'Le lac Titicaca', ARRAY['Le lac Baïkal', 'Le lac Victoria', 'Le lac Tanganyika'], 'fr', true, 'Le lac Titicaca, entre le Pérou et la Bolivie, se situe à 3 812 m d''altitude.'),
('geography', 5, 'Quel pays possède les plus anciennes roches connues de la Terre ?', 'Le Canada', ARRAY['L''Australie', 'L''Afrique du Sud', 'Le Groenland'], 'fr', true, 'Les gneiss d''Acasta au Canada sont datés de 4,03 milliards d''années.'),
('geography', 5, 'Quel est le courant océanique le plus puissant du monde ?', 'Le courant circumpolaire antarctique', ARRAY['Le Gulf Stream', 'Le Kuroshio', 'Le courant de Humboldt'], 'fr', true, 'Le courant circumpolaire antarctique transporte 130 millions de m³ d''eau par seconde.'),
('geography', 5, 'Quelle est la plus grande dépression fermée du monde ?', 'La dépression de la mer Caspienne', ARRAY['La dépression du Danakil', 'La dépression de Qattara', 'La Vallée de la Mort'], 'fr', true, 'Le bassin de la mer Caspienne est la plus grande dépression endoréique avec 3,6 millions de km².'),
('geography', 5, 'Quel volcan sous-marin est le plus grand du monde ?', 'Le Tamu Massif', ARRAY['Le Mauna Loa', 'Le Mauna Kea', 'Le mont Olympe (Mars)'], 'fr', true, 'Le Tamu Massif dans le Pacifique couvre 310 000 km², l''un des plus grands volcans du système solaire.'),
('geography', 5, 'Quel pays possède le plus long réseau ferroviaire en proportion de sa superficie ?', 'La République tchèque', ARRAY['La Belgique', 'La Suisse', 'Les Pays-Bas'], 'fr', true, 'La République tchèque a l''une des plus fortes densités de voies ferrées au monde.'),
('geography', 5, 'Quel est le glacier le plus long du monde hors des régions polaires ?', 'Le glacier Fedtchenko', ARRAY['Le glacier de Siachen', 'Le glacier Hubbard', 'Le glacier Perito Moreno'], 'fr', true, 'Le glacier Fedtchenko au Tadjikistan mesure 77 km de long dans les monts du Pamir.'),
('geography', 5, 'Quelle est la rivière la plus courte du monde ?', 'La Roe River', ARRAY['La D River', 'La Reprua', 'La Tamborasi'], 'fr', true, 'La Roe River dans le Montana mesure seulement 61 m de long.'),
('geography', 5, 'Quel pays possède le plus de biodiversité au monde ?', 'Le Brésil', ARRAY['La Colombie', 'L''Indonésie', 'Le Mexique'], 'fr', true, 'Le Brésil possède la plus grande biodiversité avec environ 15-20 % de toutes les espèces mondiales.'),
('geography', 5, 'Quel est le point le plus profond de l''océan Atlantique ?', 'La fosse de Porto Rico', ARRAY['La fosse des Sandwich du Sud', 'La fosse de Romanche', 'La fosse Caïman'], 'fr', true, 'La fosse de Porto Rico atteint 8 376 m de profondeur dans l''Atlantique Nord.'),
('geography', 5, 'Quelle île possède la plus grande diversité de langues par rapport à sa population ?', 'La Papouasie-Nouvelle-Guinée', ARRAY['L''Indonésie', 'Les Philippines', 'Madagascar'], 'fr', true, 'La Papouasie-Nouvelle-Guinée possède plus de 800 langues pour 9 millions d''habitants.'),
('geography', 5, 'Quel est le plus grand estuaire du monde ?', 'L''estuaire du Saint-Laurent', ARRAY['L''estuaire de l''Amazone', 'L''estuaire de la Gironde', 'L''estuaire du Rio de la Plata'], 'fr', true, 'L''estuaire du Saint-Laurent au Canada s''étend sur environ 370 km de longueur.'),
('geography', 5, 'Quel pays possède la frontière terrestre la plus courte du monde ?', 'Le Vatican et l''Italie (3,2 km)', ARRAY['Le Maroc et l''Espagne', 'Le Botswana et la Zambie', 'La Corée du Nord et la Russie'], 'fr', true, 'La frontière entre le Vatican et l''Italie mesure seulement 3,2 km.'),
('geography', 5, 'Quel est le plus ancien parc national du monde ?', 'Yellowstone', ARRAY['Le parc national de Banff', 'Le Royal National Park', 'Le parc national des Écrins'], 'fr', true, 'Le parc national de Yellowstone, créé en 1872 aux États-Unis, est le plus ancien au monde.'),
('geography', 5, 'Quelle est la plus haute dune de sable du monde ?', 'Cerro Blanco au Pérou', ARRAY['La dune du Pilat en France', 'Big Daddy en Namibie', 'Star Dune au Colorado'], 'fr', true, 'Cerro Blanco au Pérou mesure environ 1 176 m de hauteur.');
