('geography', 1, 'What is the capital of Egypt?', 'Cairo', ARRAY['Alexandria', 'Luxor', 'Aswan'], 'en', true, 'Cairo is the capital of Egypt and the largest city in the Arab world.'),
('geography', 1, 'Which river flows through London?', 'The Thames', ARRAY['The Seine', 'The Rhine', 'The Danube'], 'en', true, 'The River Thames flows through central London and is about 346 km long.'),
('geography', 1, 'What is the coldest continent on Earth?', 'Antarctica', ARRAY['The Arctic', 'Europe', 'Asia'], 'en', true, 'Antarctica is the coldest continent with temperatures reaching below minus 80 degrees Celsius.'),
('geography', 1, 'Which country is home to kangaroos?', 'Australia', ARRAY['South Africa', 'India', 'Brazil'], 'en', true, 'Kangaroos are native to Australia and are one of its most iconic animals.'),
